INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$89d6aa3a-0b37-5137-8ab2-48baf8650a21$ml$::uuid, $ml$agtech$ml$, 1, 1, $ml${"id": "agtech-d1-c1", "title": "The egg farmer's swinging share", "lessonTitle": "From seed to supermarket", "slot": 1, "type": "apply", "brief": {"headline": "In 2025 egg farmers got a record 82.8 cents of each retail egg dollar. In early 2026, with farm prices collapsing, their share fell to 37.6 cents.", "kicker": "Apply the chain: why do eggs give farmers such a big share?", "fullText": "USDA tracks how much of each retail dollar returns to the farmer. For fresh eggs it was 69.1 cents in 2024 and a record 82.8 cents in 2025, when bird flu made eggs scarce.\n\nEggs reach shoppers with little processing, so the farm keeps a bigger slice than it does for most foods. Then supply came back. In April 2026 Midwest white eggs sold at the farm for 35 cents a dozen, below the 79 cents it cost to produce them, and the farmer share fell to 37.6 cents in January to March.", "sources": [{"url": "https://www.fb.org/market-intel/declining-egg-prices-squeeze-farmers", "label": "Farm Bureau, declining egg prices squeeze farmers, May 2026"}, {"url": "https://www.fb.org/market-intel/farmers-receive-less-than-6-cents-of-the-food-dollar", "label": "Farm Bureau on the USDA ERS food dollar"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each fact: does it raise or lower the farmer share of the egg dollar?", "buckets": ["Raises it", "Lowers it"], "items": [{"text": "Eggs sell with very little processing", "bucket": 0}, {"text": "Bird flu makes eggs scarce at the farm", "bucket": 0}, {"text": "Farm prices fall below the cost of production", "bucket": 1}, {"text": "Supply recovers and farm prices collapse", "bucket": 1}], "explanation": "Little processing leaves more of the dollar with the farm, and scarcity lifts farm prices. A price collapse at the farm shrinks the share fast."}, "numbers": {"kind": "numberSense", "prompt": "What share of the retail egg dollar did farmers get in 2025, in cents?", "min": 0, "max": 100, "value": 83, "unit": "cents", "explanation": "A record 82.8 cents in 2025. For all food in 2024, farmers got 11.8 cents."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an egg producer. They ask why their share of the egg dollar beats a wheat farmer's share of bread.", "prompt": "Which answer shows you know the chain?", "options": ["Egg farms are larger and run far more efficiently", "Stores are required by law to mark eggs up less", "Eggs skip most processing, so less goes after the farm"], "correctIndex": 2, "consequences": ["Farm size does not decide how the retail dollar splits.", "No law sets egg markups; processing is the gap.", "You point to the stage that eats most of the food dollar."], "explanation": "Bread passes through milling, baking and packaging. Eggs go from farm to shelf almost as they are, so the farm keeps more."}, "proReasoning": "Name the stage that adds the cost. The more processing between farm and shelf, the smaller the farm share.", "commonMistake": "Explaining the share with farm size or luck instead of the chain after the farm.", "mentalModel": "Less processing, bigger farm share."}, "invest": {"call": {"kind": "theCall", "situation": "An egg producer earned record profits in 2025. Bird flu losses have eased and farm prices are falling fast.", "prompt": "What do you expect for its next results?", "options": ["Lower profits as farm prices fall", "Higher profits as supply returns", "Flat profits, since shoppers still buy eggs"], "correctIndex": 0, "consequences": ["Farm prices below cost squeeze the producer quickly.", "More supply pushed farm prices below the cost to produce.", "Steady demand does not protect margins when prices collapse."], "explanation": "In April 2026 farm prices were 44 cents a dozen below production cost. A record year can turn fast when scarcity ends."}, "proReasoning": "Investors separate scarcity profits from steady ones. When supply returns, a commodity producer gives the windfall back.", "commonMistake": "Treating a scarcity year as the new normal.", "mentalModel": "Scarcity profits fade when supply returns."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to help egg farmers earn more per dozen. Farm prices now sit below their cost.", "prompt": "Which idea fits what the chain shows?", "options": ["Lobby stores to raise shelf prices", "Help farms sell more directly to buyers", "Add a new processing step before sale"], "correctIndex": 1, "consequences": ["Shelf prices are set by stores, not by your startup.", "Fewer steps after the farm leave more of the dollar there.", "Each added step takes its own slice of the dollar."], "explanation": "The farm share is biggest where the chain is shortest. Direct sales keep more of the dollar at the farm."}, "proReasoning": "Founders look for steps they can remove, not steps they can add. A shorter chain leaves more value at the farm.", "commonMistake": "Adding a step that takes another slice of a thin margin.", "mentalModel": "Shorten the chain to raise the farm share."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says egg farmers must be rich now, since eggs cost so much in 2025.", "prompt": "What's the fuller picture in 2026?", "options": ["Farmers still keep most of each egg dollar", "Stores absorbed the losses for farmers", "Farm prices fell below the cost to produce"], "correctIndex": 2, "consequences": ["The farm share fell to 37.6 cents in early 2026.", "Stores did not cover farm losses.", "In April 2026 farms sold eggs at 35 cents a dozen."], "explanation": "Scarcity lifted farm prices in 2025. Once flocks recovered, farm prices crashed below the 79 cents a dozen it cost to produce."}, "proReasoning": "Ask what the farm gets, not what the shopper pays. The two can move very differently.", "commonMistake": "Reading high shelf prices as high farm income.", "mentalModel": "Shelf price and farm price are different numbers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7ecefb308711$ml$]::text[]),
($ml$c41bcd11-56e6-5d11-aac3-f4c34d32d1d2$ml$::uuid, $ml$agtech$ml$, 1, 2, $ml${"id": "agtech-d1-c2", "title": "Two numbers, one dollar", "lessonTitle": "From seed to supermarket", "slot": 2, "type": "connect", "brief": {"headline": "Farmers got 11.8 cents of each US food dollar in 2024. After paying for their own inputs, they kept about 5.8 cents.", "kicker": "Connect two ideas from day 1: the farm share and the inputs.", "fullText": "USDA's Food Dollar Series splits food spending into the farm share and the marketing bill. In 2024 the farm share was 11.8 cents. The 88.2-cent marketing bill paid for processing, transport, packaging, wholesale, retail and food service.\n\nThe chain also starts before the farm. Farmers buy seed, fertilizer, chemicals and machinery. Once they pay for those inputs, the farm production industry keeps about 5.8 cents of the dollar.", "sources": [{"url": "https://www.fb.org/market-intel/farmers-receive-less-than-6-cents-of-the-food-dollar", "label": "Farm Bureau on the USDA ERS food dollar"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow one food dollar from the start of the chain to your plate.", "steps": ["Input makers sell seed and fertilizer", "Farms grow the crop", "Processors turn it into food", "Stores and restaurants sell it to you"], "explanation": "Inputs come first, then the farm, then the long marketing chain that takes 88.2 cents."}, "numbers": {"kind": "numberSense", "prompt": "After paying for its own inputs, about how many cents of each food dollar does the farm keep?", "min": 0, "max": 20, "value": 6, "unit": "cents", "explanation": "About 5.8 cents. The 11.8-cent farm share shrinks once seed, fertilizer and machinery are paid."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A seed company recruiter asks where the company sits in the food chain.", "prompt": "What do you say?", "options": ["At the start, selling inputs to farms", "At the end, selling food to shoppers", "In the middle, processing crops into food"], "correctIndex": 0, "consequences": ["Seed is an input, sold to farms before anything grows.", "Stores and restaurants sell food to shoppers.", "Processors turn crops into food after harvest."], "explanation": "Seed makers sit before the farm. Their customer is the farmer, who pays for seed out of the farm share."}, "proReasoning": "Place the company on the chain and name its customer. For an input maker, the customer is the farmer.", "commonMistake": "Calling every agtech company a food company. Many never sell food at all.", "mentalModel": "Name the stage and the customer."}, "invest": {"call": {"kind": "theCall", "situation": "You compare an input maker and a large food retailer. Both depend on the same food dollar.", "prompt": "Which pool of money does the input maker draw from?", "options": ["The whole food dollar equally", "The farmer's 11.8-cent share", "The retailer's slice of the 88.2 cents"], "correctIndex": 1, "consequences": ["Each stage draws from a different slice.", "Farmers pay for inputs out of their share, leaving them about 5.8 cents.", "Retailers take part of the marketing bill, not the farm share."], "explanation": "Inputs are paid for from the farm share. That is why the farm keeps only about 5.8 cents after paying."}, "proReasoning": "Investors map which slice of the dollar pays each company. Input makers live off a slice of a slice.", "commonMistake": "Assuming every food company draws on the whole dollar.", "mentalModel": "Each stage lives on its own slice."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup can sell to farms or to food processors. Both say they need your software.", "prompt": "Which customer has more of the food dollar to spend?", "options": ["Farms, which buy inputs and equipment every year", "Both, since each sits on the same food dollar", "Processors, inside the 88.2-cent marketing bill"], "correctIndex": 2, "consequences": ["Farms keep a thin slice after inputs, which limits budgets.", "The two slices are very different in size.", "More of the dollar flows through processing and retail."], "explanation": "Most of the food dollar flows after the farm. Customers there tend to have bigger budgets."}, "proReasoning": "Founders weigh where the money pools. A customer inside the marketing bill can usually pay more than a farm.", "commonMistake": "Picking the customer you like most instead of the one with money to spend.", "mentalModel": "Sell where the dollar pools."}, "curiosity": {"call": {"kind": "theCall", "situation": "You spend $10 at the grocery store. You wonder how much the farmer actually keeps.", "prompt": "Which is closest, after the farmer pays for inputs?", "options": ["About 58 cents", "About $1.18", "About $5"], "correctIndex": 0, "consequences": ["About 5.8 cents per dollar stays with the farm after inputs.", "That is the farm share before seed and fertilizer are paid.", "Most of the $10 goes to processing, transport and retail."], "explanation": "The farm share is 11.8 cents per dollar, about $1.18 of $10. After inputs, the farm keeps about 58 cents."}, "proReasoning": "Follow the dollar twice: once to the farm, then out to the farm's own suppliers.", "commonMistake": "Stopping at the farm share and forgetting what the farmer spends to grow food.", "mentalModel": "The farm share is gross, not what the farmer keeps."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1c53fa57fbd3$ml$]::text[]),
($ml$2cdc1b0a-13ae-5f74-bdc9-c6a04069d270$ml$::uuid, $ml$agtech$ml$, 1, 3, $ml${"id": "agtech-d1-c3", "title": "Where to put the first dollar", "lessonTitle": "From seed to supermarket", "slot": 3, "type": "decide", "brief": {"headline": "Of every US food dollar in 2024, 11.8 cents went to farmers and 88.2 cents to the marketing bill. You run a small fund choosing a first agtech bet.", "kicker": "Decide: which stage of the chain do you back first?", "fullText": "You run a small fund and want one first agtech bet. The chain has four stages: input makers, farms, processors, and stores and restaurants.\n\nThe numbers frame the choice. Farmers received 11.8 cents of each food dollar in 2024 and kept about 5.8 cents after inputs. The marketing bill, 88.2 cents, paid for processing, transport, packaging, wholesale, retail and food service.", "sources": [{"url": "https://www.fb.org/market-intel/farmers-receive-less-than-6-cents-of-the-food-dollar", "label": "Farm Bureau on the USDA ERS food dollar"}]}, "evidence": {"kind": "faceOff", "prompt": "Which stage captured more of the 2024 food dollar?", "left": {"name": "Farms", "note": "11.8 cents of each dollar"}, "right": {"name": "Everything after the farm", "note": "Processing, transport, retail, food service"}, "correctIndex": 1, "explanation": "The marketing bill took 88.2 cents. In food, most of the value is added after the farm gate."}, "numbers": {"kind": "numberSense", "prompt": "How many cents of each 2024 food dollar went to the marketing bill?", "min": 0, "max": 100, "value": 88, "unit": "cents", "explanation": "About 88.2 cents went to processing, transport, packaging, wholesale, retail and food service."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The fund hires you as an analyst. Your first task is to map where agtech revenue could come from.", "prompt": "Where do you start the map?", "options": ["List the farms with the most acres", "List every stage and who pays whom", "List the startups with the biggest rounds"], "correctIndex": 1, "consequences": ["Farm size is one stage, not the whole chain.", "A payment map shows where money flows and pools.", "Round size says little about where revenue comes from."], "explanation": "A good map starts with the chain: who sells to whom, and which slice of the dollar pays them."}, "proReasoning": "Analysts start with the money flow, then place companies on it. The map shows which stages can pay.", "commonMistake": "Starting from famous startups instead of from the flow of money.", "mentalModel": "Map the money before the companies."}, "invest": {"call": {"kind": "theCall", "situation": "Two pitches arrive: a tool that helps farms, and a tool that cuts food processing costs. Both look solid.", "prompt": "Which has the bigger pool of spending to sell into?", "options": ["The farm tool", "Both pools are the same size", "The processing tool"], "correctIndex": 2, "consequences": ["Farms keep a thin slice, so budgets are tight.", "The farm share is a small part of the dollar.", "Processing sits inside the 88.2-cent marketing bill."], "explanation": "Most of the food dollar is spent after the farm. A tool there sells into a far bigger pool."}, "proReasoning": "Size the pool before judging the product. The same product sells easier where more money flows.", "commonMistake": "Assuming the farm is the biggest market because it is where food begins.", "mentalModel": "Size the pool first."}, "build_startup": {"call": {"kind": "theCall", "situation": "A founder in your fund wants to sell to farms. Farm margins are thin, about 5.8 cents per dollar after inputs.", "prompt": "What do you push the founder to prove?", "options": ["That the tool saves farms more than it costs", "That farmers find the design easy to learn", "That the tool works on every crop in the US"], "correctIndex": 0, "consequences": ["With thin margins, only clear savings get bought.", "Liking a tool does not make room in a thin budget.", "Breadth matters less than paying for itself."], "explanation": "Farms keep little of the food dollar. A farm product sells when it pays for itself in savings."}, "proReasoning": "Founders selling to farms prove a return in dollars per acre. Thin margins make payback the main pitch.", "commonMistake": "Selling features to a customer who mostly needs savings.", "mentalModel": "On thin margins, payback sells."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks most of what you pay for food goes to farmers.", "prompt": "What do you tell them?", "options": ["Most goes to sales taxes charged on food", "Most goes to processing, transport and retail", "Most goes to the farmers who grow the food"], "correctIndex": 1, "consequences": ["Taxes are not what the food dollar series measures.", "The marketing bill took 88.2 cents of each dollar.", "Farmers received 11.8 cents per dollar in 2024."], "explanation": "Of each food dollar in 2024, 88.2 cents went after the farm. Farmers got 11.8 cents."}, "proReasoning": "Picture the chain as stages, each taking a slice. The farm is one early stage.", "commonMistake": "Assuming the person who grows food gets most of the price.", "mentalModel": "Most food value is added after the farm."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d493f5c31b6b$ml$]::text[]),
($ml$32084ee3-cf17-54d1-9103-737549f7d569$ml$::uuid, $ml$agtech$ml$, 2, 1, $ml${"id": "agtech-d2-c1", "title": "When farmers stop buying tractors", "lessonTitle": "How money flows on a farm", "slot": 1, "type": "apply", "brief": {"headline": "Deere earned $5.027 billion in fiscal 2025, down from $7.1 billion the year before. Full-year sales fell from $44.8 billion to $38.9 billion.", "kicker": "Apply the farm P&L: why does a tractor maker feel farm income?", "fullText": "Deere sells tractors, combines and sprayers to farmers. In fiscal 2025 its net income fell to $5.027 billion from $7.1 billion in fiscal 2024, and full-year net sales fell to $38.9 billion from $44.8 billion. It cited margin pressure from tariffs, and it forecast fiscal 2026 net income of $4 billion to $4.75 billion.\n\nMachinery is a big purchase that farmers can delay. When sales minus costs leave little room, the new tractor waits.", "sources": [{"url": "https://www.businessrecord.com/deere-net-income-down-14-5-year-over-year-but-sales-increase/", "label": "Business Record on Deere fiscal 2025 results"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why do machinery sales fall faster than farm sales when margins shrink?", "options": ["Farmers stop planting when margins shrink", "Tractors wear out faster in bad years", "Farmers can delay big purchases like tractors"], "correctIndex": 2, "explanation": "Seed and fertilizer must be bought every year. A new tractor can wait, so it is the first spend to slip."}, "numbers": {"kind": "numberSense", "prompt": "What was Deere's fiscal 2025 net income, in billions of dollars?", "min": 0, "max": 12, "value": 5, "unit": "B", "explanation": "About $5.0 billion, down from $7.1 billion in fiscal 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a sales role at a farm equipment dealer. They ask what drives demand next year.", "prompt": "What do you point to first?", "options": ["Farm income after costs and payments", "The weather forecast for spring", "New tractor color options"], "correctIndex": 0, "consequences": ["What farms keep decides whether they can buy machinery.", "Weather matters, but income decides big purchases.", "Design changes do not move a farm budget."], "explanation": "Machinery comes out of what farms keep after costs. Net farm income is the signal dealers watch."}, "proReasoning": "Tie equipment demand to the farm income statement: sales, costs and payments. It shows you think like the buyer.", "commonMistake": "Talking about the product before the customer's ability to pay.", "mentalModel": "Farm income drives machinery demand."}, "invest": {"call": {"kind": "theCall", "situation": "Deere forecasts fiscal 2026 net income of $4 billion to $4.75 billion, below 2025.", "prompt": "What is the outlook telling you?", "options": ["Deere is losing farmers to a rival", "Farm budgets stay tight another year", "Farmers will buy more machinery soon"], "correctIndex": 1, "consequences": ["Nothing here says the share is moving to rivals.", "A lower forecast fits farms delaying big purchases.", "A falling forecast does not point to a buying wave."], "explanation": "An equipment maker's outlook reads farm budgets. A lower forecast says farms will keep holding back."}, "proReasoning": "Investors read input makers as a gauge of farm income. Their forecasts show how much farms expect to spend.", "commonMistake": "Reading a lower forecast as a company problem when it is a customer problem.", "mentalModel": "Input makers mirror farm budgets."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells an add-on that upgrades older tractors. Farmers are delaying new machines.", "prompt": "How do you pitch it now?", "options": ["Buy it with your next new tractor", "Upgrade to look modern", "Get more years from the tractor you own"], "correctIndex": 2, "consequences": ["Farms are delaying exactly that purchase.", "Looks do not justify spending in a tight year.", "It fits farms holding off on new machines."], "explanation": "When farms delay new machines, products that extend old ones fit the budget."}, "proReasoning": "Founders match the pitch to the buyer's cash position. In tight years, sell what helps them wait.", "commonMistake": "Tying your sale to a purchase the customer is putting off.", "mentalModel": "In tight years, sell the delay."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised that a tractor company earned less while food prices stayed high.", "prompt": "What's the link they're missing?", "options": ["Tractor buying follows farm margins", "Grocery stores pay for most farm tractors", "Food prices actually fell sharply in 2025"], "correctIndex": 0, "consequences": ["Farms buy machinery from what they keep after costs.", "Farmers, not stores, buy tractors.", "Farmers get only a small slice of food prices anyway."], "explanation": "High shelf prices do not mean high farm margins. Tractor buying follows what farms keep."}, "proReasoning": "Follow the money to whoever writes the check. For tractors, that is the farmer.", "commonMistake": "Linking tractor sales to grocery prices.", "mentalModel": "Follow the buyer's margin."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f09b169d78e7$ml$]::text[]),
($ml$72cc3bf0-ee49-5e05-bf1f-4f7f91a9e8db$ml$::uuid, $ml$agtech$ml$, 2, 2, $ml${"id": "agtech-d2-c2", "title": "Thin margins, many hands", "lessonTitle": "How money flows on a farm", "slot": 2, "type": "connect", "brief": {"headline": "Farmers get 11.8 cents of each food dollar. In 2026 farms expect about $540 billion in sales against $492.8 billion in costs.", "kicker": "Connect day 1 and day 2: a small share, then a thin margin.", "fullText": "Day 1 showed that farmers received 11.8 cents of each food dollar in 2024. Day 2 shows what happens inside the farm.\n\nIn 2026 US farms expect about $540 billion in sales: $253 billion from crops and $287 billion from animals. Production costs such as feed, fertilizer and livestock purchases reach $492.8 billion. Direct government payments are forecast at $47.4 billion, which is why net farm income reaches $158.4 billion.", "sources": [{"url": "https://www.fb.org/market-intel/farmers-receive-less-than-6-cents-of-the-food-dollar", "label": "Farm Bureau on the USDA ERS food dollar"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/highlights-from-the-farm-income-forecast", "label": "USDA ERS, farm income highlights"}]}, "evidence": {"kind": "sortSignal", "prompt": "Money in or money out for US farms in 2026?", "buckets": ["Money in", "Money out"], "items": [{"text": "Crop sales of $253 billion", "bucket": 0}, {"text": "Animal sales of $287 billion", "bucket": 0}, {"text": "Government payments of $47.4 billion", "bucket": 0}, {"text": "Feed and fertilizer bills", "bucket": 1}, {"text": "Livestock purchases", "bucket": 1}], "explanation": "Sales and payments come in; feed, fertilizer and livestock purchases go out. Costs eat most of the sales."}, "numbers": {"kind": "numberSense", "prompt": "Sales of about $540 billion minus costs of $492.8 billion leaves about how many billion?", "min": 0, "max": 120, "value": 47, "unit": "B", "explanation": "About $47 billion. Government payments of $47.4 billion are what lift net farm income to $158.4 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A farm lender asks you to explain 2026 farm income in one sentence.", "prompt": "Which sentence works?", "options": ["Costs fell sharply, so farm margins widened", "Sales barely beat costs, and payments fill the gap", "Record sales made farms very profitable this year"], "correctIndex": 1, "consequences": ["Costs were forecast to rise, not fall.", "Sales of $540 billion against $493 billion of costs, plus $47 billion in payments.", "High sales meant little once costs of $493 billion came out."], "explanation": "The margin between sales and costs is thin. Government payments of $47.4 billion are a large part of income."}, "proReasoning": "Speak to all three lines of the farm income statement: sales, costs and payments. Lenders listen for that.", "commonMistake": "Quoting sales as if they were profit.", "mentalModel": "Sales minus costs, plus payments."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a farm lender. Congress debates cutting direct farm payments.", "prompt": "Why does that matter to your stock?", "options": ["Payments go straight to lenders", "Payments only affect food prices", "Payments are a big part of farm income"], "correctIndex": 2, "consequences": ["Payments go to farms, not lenders.", "Payments support farm income, not shelf prices.", "Without $47.4 billion in payments, many farms would struggle to repay."], "explanation": "Payments are nearly a third of net farm income in 2026. Less income means more risk on farm loans."}, "proReasoning": "Investors treat farm policy as part of farm income. A lender's credit risk moves with it.", "commonMistake": "Ignoring policy because it is not a market price.", "mentalModel": "Policy is part of farm income."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells farm software. Farms have $540 billion in sales but only thin margins.", "prompt": "What pitch fits that P&L?", "options": ["Cut a cost line farmers already pay", "Add a new monthly expense for insight", "Raise crop sales with branding"], "correctIndex": 0, "consequences": ["Savings on a $493 billion cost base get attention.", "A new cost lands on an already thin margin.", "Most farm crops sell as commodities, not brands."], "explanation": "Costs are nearly as large as sales. A product that trims them speaks to the P&L farmers live with."}, "proReasoning": "Founders point at a cost line and promise to shrink it. On thin margins, savings beat new features.", "commonMistake": "Adding a cost without showing what it saves.", "mentalModel": "Shrink a cost the farmer already pays."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend hears farms sell $540 billion a year and assumes farming is very profitable.", "prompt": "What's missing from that view?", "options": ["Sales are counted twice", "Costs take almost all of the sales", "Farm sales are mostly exported"], "correctIndex": 1, "consequences": ["Nothing is counted twice here.", "Costs of $492.8 billion leave a thin margin.", "Exports are part of sales, not a reason they are low."], "explanation": "Sales of $540 billion meet costs of $493 billion. Payments make up much of what is left."}, "proReasoning": "Always ask what it costs to earn the sales. Big revenue can hide a thin margin.", "commonMistake": "Treating revenue as profit.", "mentalModel": "Revenue is not profit."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5f6125921483$ml$]::text[]),
($ml$9d7e3808-3893-5adf-9244-756f281d7886$ml$::uuid, $ml$agtech$ml$, 2, 3, $ml${"id": "agtech-d2-c3", "title": "If the payments stop", "lessonTitle": "How money flows on a farm", "slot": 3, "type": "decide", "brief": {"headline": "Direct government payments are forecast at $47.4 billion in 2026, up 69.8%. You manage a farm that counts on them.", "kicker": "Decide: how do you plan for a year without the payments?", "fullText": "USDA forecasts net farm income of $158.4 billion in 2026, down 2.6% from 2025. Direct government payments are expected to jump 69.8% to $47.4 billion, mostly from Farm Bill commodity payments and higher disaster aid. That is nearly a third of net farm income.\n\nYou manage a grain farm whose budget leans on these payments. Your lender asks how the farm would do if they shrank.", "sources": [{"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/highlights-from-the-farm-income-forecast", "label": "USDA ERS, farm income highlights"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about 2026 farm income. Tap it.", "statements": ["Payments are nearly a third of net farm income.", "Payments are forecast to rise 69.8%.", "Net farm income is forecast to rise sharply."], "fakeIndex": 2, "explanation": "Net farm income is forecast at $158.4 billion, down 2.6% from 2025. Payments rise; income does not."}, "numbers": {"kind": "numberSense", "prompt": "About what share of 2026 net farm income comes from direct government payments?", "min": 0, "max": 100, "value": 30, "unit": "%", "explanation": "About 30%: $47.4 billion of $158.4 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the farm manager. The lender wants a plan for a year with smaller payments.", "prompt": "What do you bring to the meeting?", "options": ["A promise that payments will continue", "A plan to plant more of everything", "A budget with and without the payments"], "correctIndex": 2, "consequences": ["No manager can promise what Congress will do.", "More acres raise costs before they raise income.", "The lender sees the risk and your plan for it."], "explanation": "Showing both budgets proves you understand how much the farm leans on policy."}, "proReasoning": "Good managers stress test the budget against policy. Lenders trust a plan that names the risk.", "commonMistake": "Treating government payments as guaranteed income.", "mentalModel": "Budget with and without the policy."}, "invest": {"call": {"kind": "theCall", "situation": "You lend to many grain farms. Payments are forecast to make up about 30% of farm income.", "prompt": "Which risk do you watch most closely?", "options": ["A cut in farm payments", "A rise in grocery prices", "A change in tractor colors"], "correctIndex": 0, "consequences": ["Losing a third of income would strain repayments.", "Grocery prices barely reach the farm.", "Design does not move farm cash flow."], "explanation": "When payments are a third of income, policy is a credit risk for every farm loan."}, "proReasoning": "Lenders map how much borrower income depends on one source. Policy-heavy income is policy risk.", "commonMistake": "Reading high farm income without asking where it came from.", "mentalModel": "Income that depends on policy carries policy risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could help farms track payment programs, or help them cut input costs.", "prompt": "Which keeps working if payments shrink?", "options": ["Both, equally", "Cutting input costs", "Tracking payment programs"], "correctIndex": 1, "consequences": ["One depends on policy and one does not.", "Savings matter in any policy year.", "A tool built on payments shrinks with them."], "explanation": "A product tied to payments rides on policy. Cost savings stay valuable whatever Congress decides."}, "proReasoning": "Founders test whether their market survives a policy change. Savings on real costs outlast any one program.", "commonMistake": "Building a business whose demand depends on one law.", "mentalModel": "Build on costs, not on policy."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that farm income will be $158.4 billion in 2026 and thinks farms are booming.", "prompt": "What's the catch?", "options": ["Income is counted before any costs are paid", "Most of that income goes to grocery stores", "About a third comes from government payments"], "correctIndex": 2, "consequences": ["Income is what is left after costs.", "Net farm income belongs to farms, not stores.", "Payments of $47.4 billion make up much of that income."], "explanation": "Without $47.4 billion in payments, farm income would be far lower."}, "proReasoning": "Ask where income comes from, not only how big it is.", "commonMistake": "Reading a headline number without its sources.", "mentalModel": "Check where the income comes from."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d0364cf44093$ml$]::text[]),
($ml$aa89e411-19c6-51aa-8f8e-8b9b671dc33c$ml$::uuid, $ml$agtech$ml$, 3, 1, $ml${"id": "agtech-d3-c1", "title": "Four packers under the microscope", "lessonTitle": "Who holds the power in agriculture", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025 the Justice Department opened a probe into Cargill, JBS, Tyson and National Beef. Together they control 85% of US beef processing.", "kicker": "Apply the power map: where do these four sit?", "fullText": "After a post by President Trump, Attorney General Pam Bondi confirmed the probe into possible collusion. The White House cited no evidence, and the Meat Institute said market transactions are transparent.\n\nThe backdrop: ground beef rose from $4.05 to $6.32 a pound between April 2020 and September 2025, more than 56%, while consumer prices rose less than 27%. The number of US calves has fallen by more than 3 million since 2018. Ranchers sell cattle to these four packers, who sell beef to stores.", "sources": [{"url": "https://www.startribune.com/cargill-beef-price-fixing-meatpacker-jbs-tyson-national-department-justice-doj-investigation-trump/601523193", "label": "Minnesota Star Tribune on the DOJ meatpacker probe, Nov 2025"}, {"url": "https://ers.usda.gov/webdocs/publications/106795/eib-256_summary.pdf?v=4878.9", "label": "USDA ERS, concentration and competition report"}]}, "evidence": {"kind": "faceOff", "prompt": "A rancher has cattle to sell this month. Who has more say over the price?", "left": {"name": "The rancher", "note": "One of many sellers"}, "right": {"name": "The big packers", "note": "Four firms process 85% of US beef"}, "correctIndex": 1, "explanation": "Ranchers sell into a market with few buyers. Few buyers hold the stronger hand on price."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did ground beef rise from April 2020 to September 2025?", "min": 0, "max": 100, "value": 56, "unit": "%", "explanation": "More than 56%, from $4.05 to $6.32 a pound. Consumer prices overall rose less than 27%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a meatpacker during the probe. They ask how you see the company's position.", "prompt": "Which answer is accurate and fair?", "options": ["A retailer that sells beef straight to shoppers", "A few large buyers between ranchers and stores", "One of thousands of small local processors"], "correctIndex": 1, "consequences": ["Packers sell to retailers; they are not the retailer.", "Four firms control 85% of beef processing.", "The market is concentrated, not scattered."], "explanation": "Packers buy from many ranchers and sell to stores. Concentration is why regulators watch them."}, "proReasoning": "Describe the position factually without taking sides on the probe. Show you know who buys from whom.", "commonMistake": "Calling the probe proof of wrongdoing; the White House cited no evidence.", "mentalModel": "State the position, not the verdict."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in a large beef packer. The DOJ has just announced a probe.", "prompt": "What risk does the probe add?", "options": ["Fewer cattle to process next year", "Lower grocery demand for beef", "Legal and regulatory risk to pricing"], "correctIndex": 2, "consequences": ["Herd size was already falling before the probe.", "The probe does not change what shoppers want.", "A probe can bring fines or limits on conduct."], "explanation": "Concentration brings pricing power, and regulators watch it closely. A probe makes that risk concrete."}, "proReasoning": "Investors price concentration in both directions: pricing power now, regulatory risk later.", "commonMistake": "Counting market share as pure upside.", "mentalModel": "Pricing power invites scrutiny."}, "build_startup": {"call": {"kind": "theCall", "situation": "Ranchers tell you they feel stuck selling to four big packers.", "prompt": "Which idea gives them a stronger hand?", "options": ["Help them reach smaller regional processors", "An app that tracks their daily weather", "A brand for their ranch on social media"], "correctIndex": 0, "consequences": ["More buyers means more bargaining power.", "Weather data does not change who buys cattle.", "A brand alone does not add buyers."], "explanation": "Power sits with whoever farmers must sell to. Adding buyers is what shifts it."}, "proReasoning": "Founders give farmers options. Each new buyer weakens the hold of the few big ones.", "commonMistake": "Building tools that leave the farmer with the same few buyers.", "mentalModel": "More buyers, a stronger hand."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why beef got so expensive.", "prompt": "Which answer fits the facts so far?", "options": ["Stores doubled their beef markups overnight", "Fewer cattle, a concentrated market, and a probe", "Ranchers raised their prices to get rich fast"], "correctIndex": 1, "consequences": ["No evidence shows overnight store markups.", "Calves fell by over 3 million, and four firms process 85%.", "Ranchers sell into a market with few buyers."], "explanation": "A smaller herd cut supply, and the market is concentrated. The probe is open; no wrongdoing is proven."}, "proReasoning": "Separate what is known, a smaller herd and concentration, from what is alleged.", "commonMistake": "Treating an investigation as a verdict.", "mentalModel": "Facts first, allegations second."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d12b4f8e09ae$ml$]::text[]),
($ml$90a6c3e6-e769-5fbe-bcf6-b1ba01e04355$ml$::uuid, $ml$agtech$ml$, 3, 2, $ml${"id": "agtech-d3-c2", "title": "Squeezed from both sides", "lessonTitle": "Who holds the power in agriculture", "slot": 2, "type": "connect", "brief": {"headline": "Two seed companies supplied 72% of US corn acres in 2018 to 2020. Four packers handled 85% of steer and heifer slaughter in 2019.", "kicker": "Connect day 2 and day 3: thin margins meet big suppliers and buyers.", "fullText": "Day 2 showed thin farm margins: about $540 billion in sales against $492.8 billion in costs in 2026. Day 3 shows who sits on each side of those margins.\n\nOn the input side, two seed companies held 72% of planted corn acres and 66% of soybean acres in 2018 to 2020. On the selling side, four meatpackers handled 85% of steer and heifer slaughter and 67% of hog slaughter in 2019. Concentration has risen sharply over four decades.", "sources": [{"url": "https://ers.usda.gov/webdocs/publications/106795/eib-256_summary.pdf?v=4878.9", "label": "USDA ERS, concentration and competition report"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each a supplier farmers buy from, or a buyer they sell to?", "buckets": ["Farmers buy from", "Farmers sell to"], "items": [{"text": "Seed companies", "bucket": 0}, {"text": "Fertilizer makers", "bucket": 0}, {"text": "Meatpackers", "bucket": 1}, {"text": "Grain buyers and processors", "bucket": 1}], "explanation": "Farmers sit between concentrated suppliers and concentrated buyers. That squeezes both sides of a thin margin."}, "numbers": {"kind": "numberSense", "prompt": "What share of US corn acres did the two largest seed companies supply in 2018 to 2020?", "min": 0, "max": 100, "value": 72, "unit": "%", "explanation": "About 72%. For soybeans it was 66%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A farm cooperative interviews you. They ask what problem a co-op solves for its members.", "prompt": "Which answer shows you get the squeeze?", "options": ["It lets member farmers skip paying for seed", "It guarantees each member a profit every year", "It gives small farms bargaining power together"], "correctIndex": 2, "consequences": ["Members still pay for inputs.", "No co-op can promise profits.", "Pooling volume helps against big suppliers and buyers."], "explanation": "Farmers face few big suppliers and buyers. Pooling volume is how they push back."}, "proReasoning": "Name both sides of the squeeze, then show how pooling helps on each.", "commonMistake": "Describing a co-op as a charity rather than a bargaining tool.", "mentalModel": "Pooling builds bargaining power."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a seed company and a grain farm. Margins at the farm are thin.", "prompt": "Which is better placed to hold its prices?", "options": ["The seed company", "The grain farm", "Neither has any pricing power"], "correctIndex": 0, "consequences": ["Two firms held 72% of corn acres, which brings pricing power.", "One farm among many sells at the market price.", "Concentrated sellers usually have some pricing power."], "explanation": "Concentration brings pricing power. The farm, one of many sellers, takes the price it is given."}, "proReasoning": "Investors look for the concentrated link in the chain. That is where pricing power sits.", "commonMistake": "Assuming every stage of the chain earns the same margins.", "mentalModel": "Power sits at the concentrated link."}, "build_startup": {"call": {"kind": "theCall", "situation": "You can build for farmers or for one of the big seed firms. Farmers face a squeeze on both sides.", "prompt": "Which farmer product is easiest to sell?", "options": ["One that only reports past yields", "One that adds a new buyer or supplier", "One that adds a monthly fee"], "correctIndex": 1, "consequences": ["Reports do not change who farmers deal with.", "New options ease the squeeze.", "A fee adds to a thin margin."], "explanation": "Anything that adds options strengthens farmers against concentrated markets."}, "proReasoning": "Founders sell options to squeezed customers. A second supplier is worth more than another report.", "commonMistake": "Adding cost without adding choice.", "mentalModel": "Sell options to the squeezed."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why farmers struggle when food sells so well.", "prompt": "Which part of the answer comes from day 3?", "options": ["They grow too many different crops each year", "They refuse to use any modern technology", "They buy and sell through a few big companies"], "correctIndex": 2, "consequences": ["Variety is not the issue the data shows.", "Many farms use advanced technology.", "Few suppliers and few buyers limit their bargaining power."], "explanation": "Farmers face concentrated markets on both sides, which squeezes an already thin margin."}, "proReasoning": "Look at who sits on each side of a business. Few suppliers and few buyers make a hard middle.", "commonMistake": "Blaming farmers instead of the market around them.", "mentalModel": "The middle of a concentrated chain gets squeezed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2eb171443c27$ml$]::text[]),
($ml$526c31da-c2d2-5a47-b10d-a485e858cd84$ml$::uuid, $ml$agtech$ml$, 3, 3, $ml${"id": "agtech-d3-c3", "title": "Sell now or join the co-op", "lessonTitle": "Who holds the power in agriculture", "slot": 3, "type": "decide", "brief": {"headline": "Four meatpackers handled 85% of US steer and heifer slaughter in 2019. You raise cattle and must decide how to sell this year.", "kicker": "Decide: how do you strengthen your hand?", "fullText": "You run a cattle operation. The buyers are few: four packers handled 85% of steer and heifer slaughter in 2019, and concentration has risen over four decades.\n\nYou can sell alone at the market price each week, contract early with a packer, or join a cooperative that pools cattle from many ranchers. The lesson's rule applies: power sits with whoever you must sell to.", "sources": [{"url": "https://ers.usda.gov/webdocs/publications/106795/eib-256_summary.pdf?v=4878.9", "label": "USDA ERS, concentration and competition report"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which option most improves your bargaining position?", "options": ["Join a co-op or contract early", "Sell alone each week at the market price", "Wait and hope prices rise"], "correctIndex": 0, "explanation": "Pooling volume or locking terms in advance reduces the hold of a few big buyers."}, "numbers": {"kind": "numberSense", "prompt": "What share of US hog slaughter did the four largest packers handle in 2019?", "min": 0, "max": 100, "value": 67, "unit": "%", "explanation": "About 67%. For steers and heifers it was 85%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work as a cattle buyer for a co-op. A rancher asks why she should join instead of selling alone.", "prompt": "What is your best answer?", "options": ["Together we negotiate with packers from strength", "Joining guarantees you the highest cattle price", "The co-op sets the beef prices in grocery stores"], "correctIndex": 0, "consequences": ["Pooled cattle give the group more say.", "No one can guarantee the top price.", "Stores set retail prices, not co-ops."], "explanation": "Few packers buy most cattle. Selling together evens the bargaining table."}, "proReasoning": "Sell the co-op on bargaining power, not on promises about price.", "commonMistake": "Overpromising results a co-op cannot control.", "mentalModel": "Promise bargaining power, not prices."}, "invest": {"call": {"kind": "theCall", "situation": "You lend to cattle ranchers. Some sell alone each week, others sell on early contracts.", "prompt": "Which borrowers carry less price risk?", "options": ["Both carry the same risk", "Those on early contracts", "Those selling alone each week"], "correctIndex": 1, "consequences": ["Contracts change the risk profile.", "Locked terms make cash flow more predictable.", "Weekly sales take whatever price the few buyers pay."], "explanation": "A contract fixes terms in advance, which steadies the cash flow a lender relies on."}, "proReasoning": "Lenders prefer predictable cash flow. Early contracts reduce a borrower's price risk.", "commonMistake": "Treating all ranchers in one market as equal credit risks.", "mentalModel": "Locked terms, steadier cash."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a tool for ranchers who sell alone. They want a better deal from packers.", "prompt": "What feature helps most?", "options": ["Track every animal's weight hourly", "Post daily ranch photos online", "Group small ranchers into one sale"], "correctIndex": 2, "consequences": ["Weights do not change bargaining power.", "Photos do not add buyers.", "A bigger lot gets more attention from buyers."], "explanation": "Bundling small sellers into larger lots works like a co-op and adds bargaining power."}, "proReasoning": "Founders can rebuild co-op power in software: pool many small sellers into one offer.", "commonMistake": "Adding data without changing the negotiation.", "mentalModel": "Pool the sellers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why ranchers join cooperatives if they could sell on their own.", "prompt": "What is the main reason?", "options": ["Selling together gives them more say", "The law requires ranchers to join one", "Co-ops pay no taxes or costs at all"], "correctIndex": 0, "consequences": ["Few buyers means individuals have little power.", "Joining a co-op is a choice.", "Co-ops have costs like any business."], "explanation": "When four packers buy most cattle, one rancher has little say. Together they have more."}, "proReasoning": "Small sellers band together when buyers are few. It is an old answer to market power.", "commonMistake": "Thinking co-ops are about tradition rather than bargaining.", "mentalModel": "Few buyers push sellers to band together."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:365f6c1ed36b$ml$]::text[]),
($ml$dd10af79-f1fa-51b6-8c46-785133329d3f$ml$::uuid, $ml$agtech$ml$, 4, 1, $ml${"id": "agtech-d4-c1", "title": "The year farm bankruptcies jumped", "lessonTitle": "The numbers that run US farming", "slot": 1, "type": "apply", "brief": {"headline": "US courts recorded 315 farm bankruptcies in 2025, up 46% from 2024. It was the second straight yearly rise, though still below the 599 filed in 2019.", "kicker": "Apply the numbers: what do rising bankruptcies say about the trend?", "fullText": "Chapter 12 is the bankruptcy chapter built for family farms. Filings rose to 315 in 2025, up 46%. The Midwest filed 121 cases and the Southeast 105, far ahead of other regions. Arkansas led the states with 33 and Georgia followed with 27.\n\nAnalysts pointed to row crop losses, weaker dairy, hog and poultry markets, and a fourth straight year of expected income declines. Behind the bankruptcies sits the longer trend from day 4: about 1.9 million farms, fewer each year, and bigger on average.", "sources": [{"url": "https://farmpolicynews.illinois.edu/2026/02/u-s-farm-bankruptcies-increased-46-in-2025/", "label": "Farm Policy News, US farm bankruptcies increased 46% in 2025"}, {"url": "https://www.dtnpf.com/agriculture/web/AG/news/article/2026/02/17/us-agriculture-loses-15-000-farms", "label": "DTN on USDA Farms and Land in Farms 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about 2025 farm bankruptcies. Tap it.", "statements": ["Filings rose 46% from 2024.", "They hit a record far above 2019.", "Arkansas had the most filings of any state."], "fakeIndex": 1, "explanation": "Filings reached 315 in 2025, well below the 599 recorded in 2019. They rose for a second straight year."}, "numbers": {"kind": "numberSense", "prompt": "How many Chapter 12 farm bankruptcies were filed in 2025?", "min": 0, "max": 800, "value": 315, "explanation": "315, up 46% from 2024. The recent peak was 599 in 2019."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an ag lender. They ask how you read the 2025 bankruptcy numbers.", "prompt": "Which answer is most balanced?", "options": ["A crisis worse than any year on record", "A sign that farming is getting easier", "Rising stress, but well below the 2019 peak"], "correctIndex": 2, "consequences": ["315 filings is about half the 599 of 2019.", "Rising filings point to more stress, not less.", "You note the trend and keep it in proportion."], "explanation": "Filings rose 46% for a second straight year, yet stayed well under the 2019 level."}, "proReasoning": "Give the change and the context in one breath: up 46%, still below 2019. Lenders want both.", "commonMistake": "Calling every rise a record crisis without checking past peaks.", "mentalModel": "Trend plus context."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a bank with many farm loans in Arkansas and Georgia.", "prompt": "What does the 2025 data suggest you check?", "options": ["Loan losses in row crop regions", "How many tractors the bank owns", "Whether grocery prices rose"], "correctIndex": 0, "consequences": ["Those two states led 2025 farm bankruptcies.", "Banks lend on equipment; they rarely own fleets.", "Grocery prices barely reach farm cash flow."], "explanation": "Arkansas had 33 filings and Georgia 27. A lender heavy in those regions faces more credit risk."}, "proReasoning": "Investors trace where stress shows up first. Regional bankruptcy data points straight at loan books.", "commonMistake": "Treating farm stress as a national average when it clusters by region.", "mentalModel": "Find where the stress clusters."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farms are under more financial stress. Your startup must pick one product to build first.", "prompt": "Which product fits a stressed customer?", "options": ["Hardware that needs a large upfront payment", "Software that cuts a big input cost", "A premium subscription for data dashboards"], "correctIndex": 1, "consequences": ["Big upfront costs are hard for stressed farms.", "Savings help a farm under pressure.", "A new subscription adds cost in a tight year."], "explanation": "When income falls for years, farms buy what saves money now, not what adds cost."}, "proReasoning": "Founders read customer stress before pricing. In tight years, products that save cash sell best.", "commonMistake": "Launching an expensive product into a downturn.", "mentalModel": "Stressed customers buy savings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend hears farm bankruptcies jumped 46% and assumes most farms are failing.", "prompt": "What's the better reading?", "options": ["Most US farms have now filed for bankruptcy", "Bankruptcy only happens to the smallest farms", "A few hundred filings among about 1.9 million farms"], "correctIndex": 2, "consequences": ["Only 315 farms filed in 2025.", "Farms of many sizes use Chapter 12.", "315 filings is a signal of stress, not mass failure."], "explanation": "315 filings is a sharp rise, but small next to about 1.9 million farms."}, "proReasoning": "Compare a count to the whole. A big percent change can still be a small number.", "commonMistake": "Reading a percent change as a share of all farms.", "mentalModel": "Check the base before the percent."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:10fd4819cf2b$ml$]::text[]),
($ml$9a8dc5f4-5db7-5387-bf2e-cd39df1ca4d5$ml$::uuid, $ml$agtech$ml$, 4, 2, $ml${"id": "agtech-d4-c2", "title": "Why farms keep getting bigger", "lessonTitle": "The numbers that run US farming", "slot": 2, "type": "connect", "brief": {"headline": "Farm costs are forecast at $492.8 billion in 2026, with fertilizer up 15.3%. Meanwhile the average US farm grew from 444 acres in 2018 to 469 in 2025.", "kicker": "Connect day 2 and day 4: thin margins push farms to grow.", "fullText": "Day 2 showed thin margins: about $540 billion in sales against $492.8 billion in costs. Fertilizer costs are forecast to jump 15.3% in 2026 and total production costs to rise 4.5%.\n\nDay 4 shows the response over time. The US had about 1.9 million farms in 2025, down about 158,200 since 2018, while the average farm grew from 444 to 469 acres. When each acre earns little, farms spread fixed costs over more acres.", "sources": [{"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}, {"url": "https://www.dtnpf.com/agriculture/web/AG/news/article/2026/02/17/us-agriculture-loses-15-000-farms", "label": "DTN on USDA Farms and Land in Farms 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the consolidation story in order.", "steps": ["Margins per acre are thin", "Costs like fertilizer rise", "Small farms struggle to cover fixed costs", "Some sell or rent out their land", "Neighbors expand and the average farm grows"], "explanation": "Thin margins and rising costs reward scale. Land moves to larger farms, and the average size climbs."}, "numbers": {"kind": "numberSense", "prompt": "What was the average size of a US farm in 2025, in acres?", "min": 0, "max": 1000, "value": 469, "unit": "acres", "explanation": "469 acres, up from 444 in 2018."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An agtech firm asks you who its customer will be in ten years.", "prompt": "Which answer follows the data?", "options": ["Fewer, larger farms buying at scale", "More small farms than today", "Mostly hobby farms near cities"], "correctIndex": 0, "consequences": ["The long trend is fewer and bigger farms.", "Farm numbers have fallen every recent year.", "The data points to scale, not hobby farms."], "explanation": "Since 2018 the US lost about 158,200 farms while the average farm grew. Customers are consolidating."}, "proReasoning": "Project the customer forward with the trend: fewer and bigger. It shows strategic thinking.", "commonMistake": "Assuming today's customer base stays the same.", "mentalModel": "Fewer, bigger customers ahead."}, "invest": {"call": {"kind": "theCall", "situation": "Two input sellers compete. One sells to thousands of small farms, one to large operations.", "prompt": "Which faces a shrinking customer count?", "options": ["Neither, since farm numbers are stable", "The one selling to small farms", "The one selling to large operations"], "correctIndex": 1, "consequences": ["Farm numbers keep falling.", "Small farms are the ones leaving.", "Large operations are growing in share."], "explanation": "Consolidation shrinks the number of small buyers while large ones grow."}, "proReasoning": "Investors ask whether a company's customers are growing or vanishing. Consolidation answers that.", "commonMistake": "Ignoring that the customer base itself is changing.", "mentalModel": "Follow where the customers are going."}, "build_startup": {"call": {"kind": "theCall", "situation": "Fertilizer costs are forecast to jump 15.3%. Your startup helps farms apply less of it.", "prompt": "Which farms do you target first?", "options": ["Tiny farms, which spend little on fertilizer", "Farms that grow no field crops", "Large farms, where savings add up fastest"], "correctIndex": 2, "consequences": ["Small fertilizer bills mean small savings.", "They may barely use fertilizer at all.", "More acres turn a small saving into a big check."], "explanation": "A saving per acre is worth more on more acres. Larger farms feel rising costs in bigger dollars."}, "proReasoning": "Founders aim savings tools at the customers with the most acres. Scale turns cents into real money.", "commonMistake": "Selling a per-acre saving to farms with few acres.", "mentalModel": "Savings scale with acres."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many family farms disappear while farmland stays farmed.", "prompt": "What is happening?", "options": ["Neighbors buy or rent the land and grow", "The land is mostly paved over for housing", "The government takes over most of the land"], "correctIndex": 0, "consequences": ["Farms get fewer and bigger as land changes hands.", "Land in farms fell, but most of it stays farmed.", "Land changes hands mainly through sales and rentals."], "explanation": "Farm numbers fall while the average farm grows. The land moves to neighbors who expand."}, "proReasoning": "Separate farm counts from farmland. The farms shrink in number; the land mostly keeps farming.", "commonMistake": "Assuming fewer farms means less farmland in equal measure.", "mentalModel": "Fewer farms, bigger farms."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0bccd2d8d657$ml$]::text[]),
($ml$6e4f2cac-f50d-5abb-9a8b-ec12c6a69a91$ml$::uuid, $ml$agtech$ml$, 4, 3, $ml${"id": "agtech-d4-c3", "title": "The neighbor's 160 acres", "lessonTitle": "The numbers that run US farming", "slot": 3, "type": "decide", "brief": {"headline": "The US lost 15,000 farms in 2025, and land in farms fell to about 874 million acres. You farm 469 acres, and your neighbor offers to sell you 160 more.", "kicker": "Decide: grow by buying, grow by renting, or stay put?", "fullText": "USDA counted about 1.9 million farms in 2025, down about 8% since 2018. Land in farms fell to about 874 million acres, 25 million fewer than in 2018, while the average farm grew from 444 to 469 acres.\n\nYou farm the average 469 acres. Your retiring neighbor offers to sell you 160 acres, or to rent them to you. Costs are rising: fertilizer is forecast up 15.3% in 2026.", "sources": [{"url": "https://www.dtnpf.com/agriculture/web/AG/news/article/2026/02/17/us-agriculture-loses-15-000-farms", "label": "DTN on USDA Farms and Land in Farms 2025"}, {"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why does adding acres help a farm like yours?", "options": ["It cuts the price the farm pays per pound of fertilizer", "It guarantees the farm higher crop prices each year", "It spreads fixed costs like machinery over more acres"], "correctIndex": 2, "explanation": "Machinery and labor cost about the same across more acres. Each acre then carries less fixed cost."}, "numbers": {"kind": "numberSense", "prompt": "By about what percent did the number of US farms fall from 2018 to 2025?", "min": 0, "max": 40, "value": 8, "unit": "%", "explanation": "About 8%. The US lost about 158,200 farms over that time."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You advise the farm as a young agronomist. The owner asks if growing makes sense.", "prompt": "What do you check before saying yes?", "options": ["Whether the land looks good from the road", "Whether extra acres cover their own costs", "Whether the neighbor is a friend"], "correctIndex": 1, "consequences": ["Looks say little about yield or cost.", "Growth only helps if each new acre pays its way.", "Friendship does not change the numbers."], "explanation": "Scale helps when the added acres earn more than they cost, including rent or loan payments."}, "proReasoning": "Advisors test growth acre by acre. Scale helps only when added acres pay for themselves.", "commonMistake": "Assuming bigger is always better.", "mentalModel": "Each acre must pay its way."}, "invest": {"call": {"kind": "theCall", "situation": "You could lend the farm money to buy the 160 acres. Costs are rising and margins are thin.", "prompt": "What worries you most about the loan?", "options": ["The farm becoming too efficient", "Land values doubling overnight", "Debt payments on top of thin margins"], "correctIndex": 2, "consequences": ["Efficiency is not a lending risk.", "Rising values would help the loan, not hurt it.", "Loan payments can strain a farm when margins shrink."], "explanation": "Buying land adds debt. With thin margins and rising costs, repayment is the core risk."}, "proReasoning": "Lenders weigh growth against repayment. Thin margins make heavy debt the main risk.", "commonMistake": "Lending on the land's value alone, ignoring cash flow.", "mentalModel": "Cash flow repays loans, not land."}, "build_startup": {"call": {"kind": "theCall", "situation": "Many farmers face this buy or rent choice. Your startup could build a tool for it.", "prompt": "What should the tool compute?", "options": ["Profit per acre of buying versus renting", "A ranking of the best tractor brands", "A map of nearby restaurants"], "correctIndex": 0, "consequences": ["It answers the decision farmers actually face.", "Tractor brands are a separate choice.", "It does not help with land decisions."], "explanation": "Farmers decide in dollars per acre. A tool that compares the options that way fits how they think."}, "proReasoning": "Founders build for a real recurring decision. Farm expansion is one many farmers face.", "commonMistake": "Building features that do not touch the decision.", "mentalModel": "Build for the decision, in dollars per acre."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why a retiring farmer would sell to a neighbor rather than keep farming.", "prompt": "Which reason fits the trend?", "options": ["Farmland in the US cannot be rented out", "Larger farms can spread costs better", "Neighbors are required to buy by law"], "correctIndex": 1, "consequences": ["Renting out land is very common.", "Scale lowers cost per acre, so neighbors can pay.", "No law requires neighbors to buy."], "explanation": "A growing neighbor spreads fixed costs over more acres, which is why land flows to bigger farms."}, "proReasoning": "See consolidation as a chain of individual choices like this one.", "commonMistake": "Thinking consolidation is forced rather than chosen.", "mentalModel": "Consolidation is many small sales."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:520b4838face$ml$]::text[]),
($ml$869a56c9-acdd-5d70-8ba8-2af5e8906bb3$ml$::uuid, $ml$agtech$ml$, 5, 1, $ml${"id": "agtech-d5-c1", "title": "Canada's canola and one big buyer", "lessonTitle": "The risk that binds farming: trade", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025 China set a preliminary 75.8% duty on Canadian canola seed. In 2024 China bought about two-thirds of Canada's canola exports.", "kicker": "Apply the trade risk: what happens when one buyer dominates?", "fullText": "China had already put a 100% tariff on Canadian canola oil and canola meal in March 2025. In August it added a preliminary 75.8% duty on canola seed, effective August 14. The dispute began with Canada's tariffs on Chinese electric vehicles.\n\nIn 2024 China bought 5.9 million tonnes of Canadian canola seed, around two-thirds of Canada's canola exports, a market worth as much as C$5 billion a year. Canada said it does not dump canola.", "sources": [{"url": "https://www.graincentral.com/news/china-slaps-anti-dumping-duty-on-canadian-canola/", "label": "Grain Central, China slaps anti-dumping duty on Canadian canola, Aug 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the canola dispute in order.", "steps": ["Canada puts tariffs on Chinese electric vehicles", "China puts a 100% tariff on canola oil and meal", "China adds a 75.8% duty on canola seed", "Canadian growers lose access to their biggest buyer"], "explanation": "A fight over cars spilled into farm trade. When one buyer takes two-thirds, its politics become the farmer's risk."}, "numbers": {"kind": "numberSense", "prompt": "What preliminary duty did China set on Canadian canola seed in August 2025?", "min": 0, "max": 120, "value": 76, "unit": "%", "explanation": "75.8%, effective August 14, 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a grain exporter. They ask what the canola dispute teaches.", "prompt": "Which lesson fits best?", "options": ["Fights outside farming can hit farm exports", "Canola is a crop with weak global demand", "Duties only affect processed foods, not seed"], "correctIndex": 0, "consequences": ["A dispute over electric vehicles reached canola growers.", "China bought about two-thirds of Canada's exports.", "The duty hit raw canola seed too."], "explanation": "The dispute started with car tariffs. Agriculture often pays for fights in other sectors."}, "proReasoning": "Show you watch trade policy as closely as weather. Farm exports are often the target of retaliation.", "commonMistake": "Treating trade disputes as separate from agriculture.", "mentalModel": "Farm exports pay for other fights."}, "invest": {"call": {"kind": "theCall", "situation": "You follow a Canadian canola crusher and a canola seed exporter. China added the seed duty.", "prompt": "Who loses its main market most directly?", "options": ["Only Chinese buyers", "The seed exporter selling to China", "Neither, since demand moves elsewhere at once"], "correctIndex": 1, "consequences": ["Canadian sellers lose sales too.", "China bought most of Canada's canola seed exports.", "Finding new buyers for that volume takes time."], "explanation": "A seller that depends on one buyer for most exports is hit hardest when that buyer closes the door."}, "proReasoning": "Investors check how concentrated a company's buyers are. Two-thirds in one country is a large exposure.", "commonMistake": "Assuming lost sales find a new home right away.", "mentalModel": "Customer concentration is a risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Canadian growers are looking for new canola buyers. Your startup runs a grain marketplace.", "prompt": "What should you build first?", "options": ["A canola recipe blog", "A tool that only tracks Chinese prices", "Links to buyers in other countries"], "correctIndex": 2, "consequences": ["Recipes do not move tonnes of seed.", "It keeps growers focused on a closed market.", "New buyers reduce growers' reliance on one market."], "explanation": "Shocks create demand for options. Connecting growers to new buyers meets that need."}, "proReasoning": "Founders turn a shock into a product by adding options. New buyers are what growers need most.", "commonMistake": "Building around the market that just closed.", "mentalModel": "After a shock, sell new options."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why electric vehicles hurt Canadian canola farmers.", "prompt": "What's the link?", "options": ["China hit back at car tariffs with farm duties", "Electric vehicles in China run on canola oil", "Canola fields were turned into new car plants"], "correctIndex": 0, "consequences": ["Canada taxed Chinese cars; China taxed canola.", "Electric vehicles do not run on canola oil.", "The fields kept growing canola."], "explanation": "Retaliation often targets farm goods. The fight over cars landed on canola growers."}, "proReasoning": "In trade fights, look for what the other side buys most. That is often what it targets.", "commonMistake": "Expecting retaliation to stay in the same industry.", "mentalModel": "Retaliation targets big purchases."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b0033c564ce8$ml$]::text[]),
($ml$c758558c-0d02-5690-bd8d-ab50a356691d$ml$::uuid, $ml$agtech$ml$, 5, 2, $ml${"id": "agtech-d5-c2", "title": "When the buyer is a country", "lessonTitle": "The risk that binds farming: trade", "slot": 2, "type": "connect", "brief": {"headline": "Four packers handled 85% of US steer and heifer slaughter in 2019. Before 2025, about half of US soybean exports went to one country: China.", "kicker": "Connect day 3 and day 5: a dominant buyer can be a country.", "fullText": "Day 3 showed concentrated buyers inside the US: four meatpackers handled 85% of steer and heifer slaughter in 2019.\n\nDay 5 shows the same pattern abroad. About half of exported US soybeans went to China in recent years. During the 2025 tariff talks China stopped buying and turned to South America. A later deal promised 12 million tons in 2025 and at least 25 million a year through 2028, yet from September through March China took less than 30% of US soybean exports.", "sources": [{"url": "https://ers.usda.gov/webdocs/publications/106795/eib-256_summary.pdf?v=4878.9", "label": "USDA ERS, concentration and competition report"}, {"url": "https://southdakotasearchlight.com/?p=23253", "label": "South Dakota Searchlight on China soybean purchases"}]}, "evidence": {"kind": "faceOff", "prompt": "In 2025, who held more power over US soybean prices?", "left": {"name": "US soybean farmers", "note": "Many sellers with a crop to move"}, "right": {"name": "China as a buyer", "note": "Took about half of exports before 2025"}, "correctIndex": 1, "explanation": "A buyer that takes half your exports holds the stronger hand, whether it is a company or a country."}, "numbers": {"kind": "numberSense", "prompt": "Under the deal, at least how many million tons a year was China to buy through 2028?", "min": 0, "max": 60, "value": 25, "unit": "M", "explanation": "At least 25 million tons a year, after 12 million tons in 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A soybean trade group asks you to summarize its biggest risk.", "prompt": "What do you write?", "options": ["Shoppers eating less tofu", "Too much reliance on one export buyer", "Too many soybean varieties on the market"], "correctIndex": 1, "consequences": ["Most soybeans go to feed and oil, not tofu.", "China took about half of exports before 2025.", "Variety is not the risk the data shows."], "explanation": "When one buyer takes half your exports, its politics become your risk."}, "proReasoning": "Name the concentration and its source. Half of exports to one buyer is the headline risk.", "commonMistake": "Listing many small risks and missing the big one.", "mentalModel": "Find the dominant buyer."}, "invest": {"call": {"kind": "theCall", "situation": "China signed a deal to buy US soybeans, but bought less than promised for months.", "prompt": "How do you treat the deal?", "options": ["As guaranteed demand through 2028", "As irrelevant to soybean prices", "As a promise to verify with shipments"], "correctIndex": 2, "consequences": ["China took under 30% of exports for months.", "A buyer this large moves prices.", "Actual purchases fell short of the deal's pace."], "explanation": "Deals are promises. Investors track shipments, which showed China buying well below its old share."}, "proReasoning": "Investors check deals against delivery data. Shipments tell you more than signatures.", "commonMistake": "Pricing a trade deal as if it were already delivered.", "mentalModel": "Trust shipments over announcements."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers want to know when China is really buying. Your startup has shipping data.", "prompt": "What product do you build?", "options": ["Weekly tracking of actual export shipments", "A forecast of the next trade deal headline", "A soybean price meme channel"], "correctIndex": 0, "consequences": ["Real shipments show whether promises are kept.", "Headlines often differ from what is shipped.", "Entertainment does not help sales timing."], "explanation": "The gap between promises and shipments is where farmers need information."}, "proReasoning": "Founders find value where official promises and real behavior diverge.", "commonMistake": "Building around announcements rather than data.", "mentalModel": "Sell the gap between promise and delivery."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one country could hurt US soybean farmers so quickly.", "prompt": "What is the key fact?", "options": ["US farmers sell only to China by law", "China bought about half of US soybean exports", "China grows most of the world's soybeans"], "correctIndex": 1, "consequences": ["No law limits who US farmers sell to.", "Losing a buyer that large hits prices fast.", "Brazil and the US grow far more soybeans."], "explanation": "When one buyer takes half of exports, its absence is felt quickly."}, "proReasoning": "Ask how big the buyer is relative to the market. Size explains the speed of the hit.", "commonMistake": "Assuming export markets are spread evenly.", "mentalModel": "A dominant buyer moves the market."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4702a96c921e$ml$]::text[]),
($ml$a5db9f8c-ba9b-5bf2-85bb-1d9b0f3c3687$ml$::uuid, $ml$agtech$ml$, 5, 3, $ml${"id": "agtech-d5-c3", "title": "Diversify or double down", "lessonTitle": "The risk that binds farming: trade", "slot": 3, "type": "decide", "brief": {"headline": "Tennessee soybean farmers alone lost nearly $110 million in 2025 when China stopped buying. You grow soybeans and plan next season.", "kicker": "Decide: how do you reduce your exposure to one buyer?", "fullText": "In 2025 China stopped buying US soybeans during tariff talks and turned to South American suppliers. A later deal committed it to 12 million metric tons in 2025 and at least 25 million tons a year through 2028. Yet from September through March it took less than 30% of US soybean exports, about half its previous share.\n\nTennessee soybean farmers lost nearly $110 million in 2025, and prices still may not cover production costs. You grow soybeans and must plan next season.", "sources": [{"url": "https://southdakotasearchlight.com/?p=23253", "label": "South Dakota Searchlight on China soybean purchases"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["China turned to South American suppliers.", "The halt raised US soybean farmers' profits.", "Tennessee growers lost nearly $110 million."], "fakeIndex": 1, "explanation": "The halt cut demand and prices. Growers lost money; profits did not rise."}, "numbers": {"kind": "numberSense", "prompt": "From September through March, China took less than what share of US soybean exports?", "min": 0, "max": 100, "value": 30, "unit": "%", "explanation": "Less than 30%, about half its previous share of roughly 50%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work for a farm marketing advisor. A soybean client asks how to cut risk next season.", "prompt": "What do you recommend?", "options": ["Plant only soybeans and wait for China", "Stop selling until prices double", "Diversify crops and buyers"], "correctIndex": 2, "consequences": ["It doubles the exposure that just hurt them.", "Holding grain indefinitely has its own costs.", "Spreading crops and buyers limits the damage of one shock."], "explanation": "When one buyer dominates, spreading crops and buyers reduces the risk its politics create."}, "proReasoning": "Advisors reduce single points of failure. Diversity in crops and buyers is the standard answer.", "commonMistake": "Betting the farm on one buyer returning.", "mentalModel": "Spread crops and buyers."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two farm suppliers. One sells only to soybean growers, the other to many crops.", "prompt": "Which is more exposed to the China shock?", "options": ["The soybean-only supplier", "The supplier to many crops", "Both are equally exposed"], "correctIndex": 0, "consequences": ["Its customers took the direct hit.", "Its risk is spread across crops.", "Their exposure differs a lot."], "explanation": "A supplier tied to one crop inherits that crop's trade risk."}, "proReasoning": "Investors trace trade shocks to suppliers. Exposure flows down the chain.", "commonMistake": "Thinking only farmers feel a trade shock.", "mentalModel": "Trade risk flows down the chain."}, "build_startup": {"call": {"kind": "theCall", "situation": "Soybean growers want options after losing China. Your startup helps farmers trial new crops.", "prompt": "How do you pitch it?", "options": ["Switch every one of your acres this year", "A new crop lowers your reliance on one buyer", "Soybeans are finished for good in the US"], "correctIndex": 1, "consequences": ["Switching everything at once is its own big bet.", "It speaks to the risk growers just felt.", "Overstating the case loses trust."], "explanation": "Shocks create demand for options. A measured shift to new crops sells better than a full switch."}, "proReasoning": "Founders frame new options as risk reduction, not as abandoning what works.", "commonMistake": "Overselling a full switch after one bad year.", "mentalModel": "Sell options as insurance."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why farmers did not just sell their soybeans to someone else.", "prompt": "What's the main obstacle?", "options": ["Soybeans cannot be exported elsewhere", "Farmers are not allowed to change buyers", "No other buyer could absorb that much at once"], "correctIndex": 2, "consequences": ["Other countries do import soybeans.", "Farmers can sell to any buyer.", "China took about half of exports; others buy far less."], "explanation": "Replacing a buyer that takes half of exports takes time and lower prices."}, "proReasoning": "Ask whether other buyers have room for the volume. Usually they do not, at least not fast.", "commonMistake": "Assuming lost sales simply move to another buyer.", "mentalModel": "Big buyers are hard to replace."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1a8b0a3278c9$ml$]::text[]),
($ml$e120210d-6329-5cb0-b215-277734b1a50a$ml$::uuid, $ml$agtech$ml$, 6, 1, $ml${"id": "agtech-d6-c1", "title": "Plenty raised $940 million, then filed", "lessonTitle": "The vertical farming bust", "slot": 1, "type": "apply", "brief": {"headline": "In March 2025 vertical farm Plenty filed for Chapter 11. It had raised about $940 million since 2014 from backers including SoftBank, Bezos Expeditions and Walmart.", "kicker": "Apply the lesson: why did money not save the model?", "fullText": "Plenty grew produce indoors in stacked layers. Its rounds included $200 million led by SoftBank in 2017 and $200 million in 2022 with Walmart. In March 2025 it filed for Chapter 11, aiming to restructure in response to market and capital challenges. It kept its Richmond, Virginia vertical strawberry farm and its Laramie, Wyoming research site, and secured $20.7 million in debtor financing.\n\nIt followed Bowery, which shut in November 2024 after raising more than $700 million.", "sources": [{"url": "https://www.hortidaily.com/article/9717222/from-billion-dollar-backing-to-bankruptcy-plenty-restructures-for-a-leaner-focused-future", "label": "HortiDaily, Plenty files for bankruptcy, Mar 2025"}, {"url": "https://techcrunch.com/2024/11/04/bowery-farming-is-ceasing-operations/", "label": "TechCrunch, Bowery Farming is ceasing operations"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does Plenty's narrowed focus on premium strawberries suggest?", "options": ["Leafy greens had no supermarket buyers at all", "It needed a crop with a price high enough to cover costs", "Strawberries are the cheapest crop to grow indoors"], "correctIndex": 1, "explanation": "Indoor farming is costly. A premium crop has a better chance of earning more than it costs to grow."}, "numbers": {"kind": "numberSense", "prompt": "About how much had Plenty raised, in millions of dollars, before filing?", "min": 0, "max": 1500, "value": 940, "unit": "M", "explanation": "About $940 million since 2014."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An indoor farming startup offers you a job. It has raised a lot of money.", "prompt": "What do you ask before joining?", "options": ["How many of our investors are household names?", "What does a pound cost us versus field growers?", "How large was the last funding round we raised?"], "correctIndex": 1, "consequences": ["Famous backers did not prevent bankruptcy.", "Unit cost decides whether the business can last.", "Plenty raised about $940 million and still filed."], "explanation": "Funding buys time, not a business model. Cost per pound against field crops decides survival."}, "proReasoning": "Ask about unit economics before funding. Jobs are safest where the product beats the old way on cost.", "commonMistake": "Taking a big funding round as proof the business works.", "mentalModel": "Funding is time, not proof."}, "invest": {"call": {"kind": "theCall", "situation": "A vertical farm pitches you after Plenty's bankruptcy. It says it is different.", "prompt": "What evidence matters most?", "options": ["A famous chef using its greens", "The size of its new facility", "Unit margins at full scale"], "correctIndex": 2, "consequences": ["Endorsements do not cover costs.", "Bigger buildings raised costs for others.", "Margins show if it can ever compete."], "explanation": "Bowery and Plenty raised over $1.6 billion between them before failing. Margins, not size, matter."}, "proReasoning": "Investors demand proof of unit margins before more capital. Size only magnifies a bad margin.", "commonMistake": "Funding scale before proving the unit works.", "mentalModel": "Prove the unit, then scale."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to start an indoor farm after Plenty's fall.", "prompt": "Which crop strategy makes most sense?", "options": ["A premium crop where indoor growing has an edge", "Cheap lettuce sold against field farms at scale", "Every crop at once to spread the risk widely"], "correctIndex": 0, "consequences": ["A premium price can cover indoor costs.", "That is the model that failed for Bowery.", "Spreading thin raises costs everywhere."], "explanation": "Your real rival is the cheap field crop. Build where controlled growing earns a premium."}, "proReasoning": "Founders pick crops where indoor growing has a real edge. Competing with cheap field lettuce failed.", "commonMistake": "Repeating a model that failed with more money.", "mentalModel": "Compete where you have an edge."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company with nearly $1 billion could go bankrupt growing food.", "prompt": "What is the short answer?", "options": ["Nobody wanted to buy fresh produce", "It cost more to grow than it could charge", "It ran out of seeds to plant indoors"], "correctIndex": 1, "consequences": ["People buy produce; the price was the issue.", "Indoor costs beat what shoppers would pay.", "Seeds were never the problem."], "explanation": "Big funding cannot fix a product that costs more to make than it sells for."}, "proReasoning": "When a well-funded company fails, look at cost versus price first.", "commonMistake": "Assuming money alone makes a business succeed.", "mentalModel": "Cost must beat price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c910fcd41f9d$ml$]::text[]),
($ml$66276b5d-a66a-54f0-93fa-be48d128f0dc$ml$::uuid, $ml$agtech$ml$, 6, 2, $ml${"id": "agtech-d6-c2", "title": "Selling greens into an 11-cent world", "lessonTitle": "The vertical farming bust", "slot": 2, "type": "connect", "brief": {"headline": "Farmers get 11.8 cents of each food dollar, and most value comes after the farm. Bowery raised over $700 million to grow greens indoors, then shut in 2024.", "kicker": "Connect day 1 and day 6: a costly farm in a low-share chain.", "fullText": "Day 1 showed that farmers received 11.8 cents of each food dollar in 2024; the rest goes to processing, transport and retail.\n\nDay 6 shows what happens when a farm costs far more to run. Vertical farms grow crops in stacked indoor layers under artificial light. Bowery Farming, valued at more than $2 billion in 2021, shut in November 2024 after raising more than $700 million. AeroFarms and AppHarvest went bankrupt in 2023.", "sources": [{"url": "https://www.fb.org/market-intel/farmers-receive-less-than-6-cents-of-the-food-dollar", "label": "Farm Bureau on the USDA ERS food dollar"}, {"url": "https://techcrunch.com/2024/11/04/bowery-farming-is-ceasing-operations/", "label": "TechCrunch, Bowery Farming is ceasing operations"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each point help or hurt an indoor lettuce farm?", "buckets": ["Helps", "Hurts"], "items": [{"text": "Fresh produce close to cities all year", "bucket": 0}, {"text": "Steady supply in any weather", "bucket": 0}, {"text": "Power for artificial light around the clock", "bucket": 1}, {"text": "Competing with cheap field-grown lettuce", "bucket": 1}], "explanation": "Indoor farms promised freshness and steady supply. High energy costs and cheap field crops worked against them."}, "numbers": {"kind": "numberSense", "prompt": "Bowery was valued at more than how many billion dollars in 2021?", "min": 0, "max": 10, "value": 2, "unit": "B", "explanation": "More than $2 billion. It shut down three years later."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why vertical farming struggled.", "prompt": "Which answer uses both lessons?", "options": ["Shoppers strongly dislike lettuce grown indoors", "Big stores refused to stock any indoor produce", "High farm costs in a chain that pays farms little"], "correctIndex": 2, "consequences": ["Demand was not the main issue.", "Bowery sold through grocery stores.", "Farms get a small share, and indoor farms cost more to run."], "explanation": "The farm stage earns little of the food dollar, and indoor growing raised the farm's costs sharply."}, "proReasoning": "Combine the value chain with unit costs. A costly farm stage in a low-share chain is hard to fund.", "commonMistake": "Blaming consumers instead of the economics.", "mentalModel": "High costs at a low-share stage fail."}, "invest": {"call": {"kind": "theCall", "situation": "A vertical farm says it will win by selling directly to stores at a premium.", "prompt": "What do you test first?", "options": ["Whether the premium covers its higher costs", "Whether stores like its packaging design", "Whether its founders are well known names"], "correctIndex": 0, "consequences": ["A premium only helps if it beats the cost gap.", "Packaging does not close a cost gap.", "Fame did not save Bowery."], "explanation": "Indoor costs are far above field costs. The premium has to cover that gap with room to spare."}, "proReasoning": "Investors compare the premium to the cost gap. If the gap is bigger, the model loses money.", "commonMistake": "Accepting a premium price as the answer without the cost math.", "mentalModel": "The premium must beat the cost gap."}, "build_startup": {"call": {"kind": "theCall", "situation": "You see value in indoor growing but know farms earn little of the food dollar.", "prompt": "Where could you build instead?", "options": ["Compete head on with field farms on price", "Sell tools to farms that already make money", "Run your own large indoor lettuce farm"], "correctIndex": 1, "consequences": ["Field farms win on price.", "You avoid carrying the farm's high costs yourself.", "That is the model that failed repeatedly."], "explanation": "Selling tools to profitable growers avoids betting on the farm stage's thin share."}, "proReasoning": "Founders can sell picks and shovels instead of farming themselves.", "commonMistake": "Taking on the costliest stage of a low-margin chain.", "mentalModel": "Sell tools, not the farm."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks indoor lettuce should be cheaper since it avoids bad weather.", "prompt": "Why was it not?", "options": ["Indoor lettuce grows much more slowly", "Indoor farms pay heavy extra taxes", "Light, power and buildings cost a lot"], "correctIndex": 2, "consequences": ["Growth speed was not the core problem.", "No special tax explains it.", "Energy and buildings outweigh weather savings."], "explanation": "Indoor farms replace free sunlight with costly power and buildings."}, "proReasoning": "Count what a new method adds, not only what it removes.", "commonMistake": "Seeing the saved risk but not the added cost.", "mentalModel": "Free sunlight is hard to beat."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1eb1ee77b191$ml$]::text[]),
($ml$2dc83e04-502f-5e62-a9e1-419f589d4691$ml$::uuid, $ml$agtech$ml$, 6, 3, $ml${"id": "agtech-d6-c3", "title": "The indoor farm pitch", "lessonTitle": "The vertical farming bust", "slot": 3, "type": "decide", "brief": {"headline": "Bowery shut in November 2024 after raising over $700 million. AeroFarms and AppHarvest went bankrupt in 2023. You run a fund, and an indoor farm asks you to invest.", "kicker": "Decide: what must this pitch prove before you invest?", "fullText": "Three of the best-funded indoor farms went bankrupt or shut down within about two years. Bowery raised more than $700 million, AeroFarms more than $300 million, and AppHarvest went public at a $1 billion valuation before filing for bankruptcy in 2023.\n\nYou run a fund. A new indoor farm selling leafy greens to supermarkets asks you to lead its next round. The rule from day 6: a new way of growing must beat the old way on cost, not just on promise.", "sources": [{"url": "https://techcrunch.com/2024/11/04/bowery-farming-is-ceasing-operations/", "label": "TechCrunch, Bowery Farming is ceasing operations"}]}, "evidence": {"kind": "faceOff", "prompt": "Which is the indoor farm's real competitor?", "left": {"name": "Cheap field-grown greens", "note": "Grown outdoors at low cost"}, "right": {"name": "Other indoor farms", "note": "Also stacked and lit indoors"}, "correctIndex": 0, "explanation": "Shoppers compare against field-grown greens. Indoor farms had to beat that price, not each other."}, "numbers": {"kind": "numberSense", "prompt": "AppHarvest went public at a valuation of about how many billion dollars?", "min": 0, "max": 5, "value": 1, "unit": "B", "explanation": "About $1 billion. It filed for bankruptcy in 2023."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the fund's junior analyst. The partner asks for one test to run first.", "prompt": "Which test do you propose?", "options": ["Cost per pound versus field farms", "Customer reviews of the greens", "Number of press articles"], "correctIndex": 0, "consequences": ["It tests whether the farm can ever compete.", "Good taste does not cover high costs.", "Press did not save Bowery."], "explanation": "Indoor farms failed on cost. The first test is cost per pound against field-grown greens."}, "proReasoning": "Analysts start with the number that killed the last companies. Here that is cost per pound.", "commonMistake": "Starting with soft signals like reviews.", "mentalModel": "Test what killed the last ones."}, "invest": {"call": {"kind": "theCall", "situation": "The farm says its costs will fall once it builds three more facilities.", "prompt": "How do you respond?", "options": ["Pass because indoor farming never works", "Show it at one site before funding three", "Fund all three now to reach scale"], "correctIndex": 1, "consequences": ["Some premium crops may work; the test decides.", "Proof at one site limits your risk.", "Funding scale first is how others lost billions."], "explanation": "Bowery and others scaled before proving margins. Ask for proof at one site first."}, "proReasoning": "Investors stage capital against proof. Scale should follow working unit margins.", "commonMistake": "Funding the promise of scale before the unit works.", "mentalModel": "Stage money against proof."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are the founder pitching. You know investors fear another Bowery.", "prompt": "What do you lead with?", "options": ["The size of your vision", "Your list of famous advisors", "Margins from your first site"], "correctIndex": 2, "consequences": ["Vision is what earlier failures sold too.", "Advisors do not prove costs.", "Real margins answer the fear directly."], "explanation": "After Bowery, investors need evidence of margins, not bigger promises."}, "proReasoning": "Founders answer the investor's biggest fear first. Here that means proven margins.", "commonMistake": "Selling vision to investors burned by vision.", "mentalModel": "Answer the fear with data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads that a new indoor farm raised money and asks if this one will work.", "prompt": "What would you want to know?", "options": ["Whether it grows cheaper than field farms", "Whether its building looks impressive", "Whether it uses the newest LED lights"], "correctIndex": 0, "consequences": ["Cost against field crops decides survival.", "Impressive buildings cost money.", "New lights alone did not save others."], "explanation": "The test is simple: can it grow food cheaply enough to compete?"}, "proReasoning": "Judge new farming models on cost, not on how modern they look.", "commonMistake": "Being impressed by technology instead of numbers.", "mentalModel": "Cost beats looks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a3d00a49700d$ml$]::text[]),
($ml$932dc3bb-f4ed-50c0-9cd4-d6234a811089$ml$::uuid, $ml$agtech$ml$, 7, 1, $ml${"id": "agtech-d7-c1", "title": "Indiana's acre-by-acre verdict", "lessonTitle": "The farm P&L, one acre at a time", "slot": 1, "type": "apply", "brief": {"headline": "Purdue's 2026 crop budgets put the break-even price on average Indiana soil at $5.34 a bushel for corn and $12.47 for soybeans. Expected prices sat well below both.", "kicker": "Apply the acre P&L: which crop pays better per acre?", "fullText": "Purdue economists build a budget for one acre of each crop. For 2026, on average productivity soil, the contribution margin was $202 an acre for rotation corn and $263 for rotation soybeans, a $61 edge for soybeans. That margin covers variable costs only, before land and overhead.\n\nAfter all costs, projected 2026 earnings were well below zero, because expected prices sat under the break-even prices. Purdue expected cash rents to hold steady or face downward pressure.", "sources": [{"url": "https://ag.purdue.edu/commercialag/home/resource/2026/02/what-2026-crop-budgets-mean", "label": "Purdue, what 2026 crop budgets mean, Feb 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Corn shows a $202 contribution margin, yet earnings are below zero. How can both be true?", "options": ["The margin is before land and overhead costs", "Corn yields were not counted in the budget", "The margin is counted twice in earnings"], "correctIndex": 0, "explanation": "Contribution margin covers variable costs only. Land, machinery and overhead come out after, which pushes earnings below zero."}, "numbers": {"kind": "numberSense", "prompt": "What was Purdue's 2026 break-even corn price on average soil, in dollars per bushel?", "min": 0, "max": 12, "value": 5.3, "unit": "$", "explanation": "$5.34 a bushel. For soybeans it was $12.47."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a farm management firm. They ask you to explain a contribution margin.", "prompt": "Which answer is right?", "options": ["Revenue minus every cost of the farm", "Total sales before any costs at all", "Revenue minus variable costs, before land"], "correctIndex": 2, "consequences": ["That is closer to earnings, after all costs.", "That is revenue, not a margin.", "It is what is left to pay for land and overhead."], "explanation": "Contribution margin is revenue minus variable costs. Land and overhead come after it."}, "proReasoning": "Separate the margin layers clearly: contribution margin first, then earnings after all costs.", "commonMistake": "Calling a positive contribution margin a profit.", "mentalModel": "Margin first, earnings after."}, "invest": {"call": {"kind": "theCall", "situation": "You own Indiana farmland that you rent out. Purdue projects earnings below zero for 2026.", "prompt": "What should you expect for rent?", "options": ["Steady or downward pressure on rent", "A sharp rise in rent next year", "No link between earnings and rent"], "correctIndex": 0, "consequences": ["Tenants losing money push back on rent.", "Losses make rent increases hard to win.", "Rent follows what the land can earn."], "explanation": "Purdue expected rents to hold or face downward pressure, since earnings were low for several years."}, "proReasoning": "Landowners read tenant budgets. When the acre loses money, rent stops rising.", "commonMistake": "Expecting rent to climb while tenants lose money.", "mentalModel": "Rent follows what the acre earns."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers face prices below break-even. Your startup wants to help them per acre.", "prompt": "Which promise lands best?", "options": ["Get more detailed weather alerts each day", "Lower your break-even by a set amount per acre", "Grow a prettier crop this season"], "correctIndex": 1, "consequences": ["Alerts help only if they change costs or yield.", "A lower break-even closes the gap to market prices.", "Looks do not change the acre P&L."], "explanation": "When prices sit below break-even, anything that lowers break-even per acre matters most."}, "proReasoning": "Founders speak in the farmer's unit: dollars per acre and break-even per bushel.", "commonMistake": "Pitching features without a per-acre number.", "mentalModel": "Lower the break-even."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why farmers keep planting if budgets show losses.", "prompt": "Which reason fits the budget?", "options": ["Most farmers never look at crop budgets", "Grocery stores pay back the losses later", "The crop covers its variable costs"], "correctIndex": 2, "consequences": ["Farmers use budgets to make these calls.", "Stores do not repay farm losses.", "A positive margin helps pay fixed costs that exist anyway."], "explanation": "Land and machinery cost money whether or not the farmer plants. A crop that covers its variable costs still helps pay them."}, "proReasoning": "Some costs exist whether you plant or not. A crop that covers its own costs still helps.", "commonMistake": "Thinking any loss means stopping is better.", "mentalModel": "Cover variable costs, chip away at fixed ones."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b9009ebbb63d$ml$]::text[]),
($ml$9d0f45e6-6ce6-5227-a18d-c370c5ec59e7$ml$::uuid, $ml$agtech$ml$, 7, 2, $ml${"id": "agtech-d7-c2", "title": "From the national P&L to one acre", "lessonTitle": "The farm P&L, one acre at a time", "slot": 2, "type": "connect", "brief": {"headline": "US farms expect $540 billion in sales against $492.8 billion in costs in 2026. In Illinois, corn on rented land was projected to lose $45 to $53 an acre.", "kicker": "Connect day 2 and day 7: the same squeeze, acre by acre.", "fullText": "Day 2 showed the national farm P&L: about $540 billion in sales, $492.8 billion in costs, and $47.4 billion in government payments in 2026.\n\nDay 7 shows the same squeeze on one acre. In May 2026 University of Illinois economists projected that corn on rented land in northern and central Illinois would lose about $45 to $53 an acre at $4.50 a bushel. Corn needed about $4.80 to break even after all costs; soybeans showed a small positive return.", "sources": [{"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}, {"url": "https://farmdocdaily.illinois.edu/2026/05/spring-revision-to-2026-illinois-crop-budgets.html", "label": "farmdoc daily, spring revision to 2026 Illinois crop budgets"}]}, "evidence": {"kind": "buildChain", "prompt": "Build a one-acre corn budget in order.", "steps": ["Estimate yield in bushels per acre", "Multiply by the expected price", "Subtract seed, fertilizer and other costs", "Subtract rent for the land", "What is left is the return per acre"], "explanation": "Revenue is yield times price. Costs and rent come out next. At $4.50 corn, rented acres came out negative."}, "numbers": {"kind": "numberSense", "prompt": "What corn price did Illinois rented acres need to break even in 2026, in dollars per bushel?", "min": 0, "max": 8, "value": 4.8, "unit": "$", "explanation": "About $4.80 a bushel. The budget assumed $4.50."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A crop insurance agency asks why acre budgets matter more than national totals for its clients.", "prompt": "What do you say?", "options": ["Each farmer decides one acre at a time", "National totals are always wrong", "Acre budgets ignore costs"], "correctIndex": 0, "consequences": ["Decisions happen per field, per acre.", "National totals are useful context, not wrong.", "Acre budgets are built around costs."], "explanation": "National totals describe the sector. Farmers choose crops and rent acre by acre."}, "proReasoning": "Link the big picture to the farmer's unit. Sector squeezes show up as dollars per acre.", "commonMistake": "Quoting national figures to a farmer making a field decision.", "mentalModel": "Decisions happen per acre."}, "invest": {"call": {"kind": "theCall", "situation": "You compare owned and rented corn acres in Illinois. Rented acres lose $45 to $53.", "prompt": "Why do rented acres look worse?", "options": ["Owners always get higher prices for corn", "Rent is a cash cost owners avoid", "Rented land always yields much less corn"], "correctIndex": 1, "consequences": ["Corn prices do not depend on ownership.", "Rent pushes the rented acre below break-even.", "Yield depends on soil, not who owns it."], "explanation": "Cash rent is a big cost on rented acres. It is the line that tips them into losses."}, "proReasoning": "Investors split owned and rented economics. Rent decides whether the rented acre pays.", "commonMistake": "Treating all acres of a crop as one P&L.", "mentalModel": "Rent decides the rented acre."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could help farmers with national market data or with field-level budgets.", "prompt": "Which helps their next decision more?", "options": ["National income charts by year", "Global food price headlines each week", "Field-level budgets in dollars per acre"], "correctIndex": 2, "consequences": ["Useful context, but not a field decision.", "Headlines do not tell a farmer what to plant.", "It matches how farmers decide."], "explanation": "Farmers plant and rent field by field. Tools in dollars per acre fit the decision."}, "proReasoning": "Founders build in the decision unit of the user. For farmers, that is the acre.", "commonMistake": "Giving farmers sector data when they need field math.", "mentalModel": "Build in the user's unit."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders how a farm can lose money on corn while total farm income is $158 billion.", "prompt": "What explains it?", "options": ["Totals mix many farms, crops and payments", "Corn is not part of farm income", "Income totals are measured in acres"], "correctIndex": 0, "consequences": ["Some acres lose, others earn, and payments add income.", "Corn is a large part of farm sales.", "Income totals are in dollars."], "explanation": "A national total hides wide differences between acres, crops and farms."}, "proReasoning": "A total can be positive while many of its parts lose money.", "commonMistake": "Assuming every farm matches the national average.", "mentalModel": "Totals hide the spread."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0fe3dbf128b6$ml$]::text[]),
($ml$2e981ecf-6e2a-520b-aefc-01a1d69a43ae$ml$::uuid, $ml$agtech$ml$, 7, 3, $ml${"id": "agtech-d7-c3", "title": "Corn or soybeans on the back 80", "lessonTitle": "The farm P&L, one acre at a time", "slot": 3, "type": "decide", "brief": {"headline": "At $4.50 corn, rented Illinois corn acres were projected to lose $45 to $53 each in 2026, while soybeans showed a small positive return. You farm 80 rented acres.", "kicker": "Decide: what goes on the rented 80 this year?", "fullText": "University of Illinois economists projected in May 2026 that corn on rented land in northern and central Illinois would lose about $45 to $53 an acre at $4.50 a bushel and trend yields. Corn needed about $4.80 to break even. Soybeans looked better, with a small positive return.\n\nYou farm 80 rented acres and must choose what to plant. The rule from day 7: on a farm, every decision comes down to dollars per acre.", "sources": [{"url": "https://farmdocdaily.illinois.edu/2026/05/spring-revision-to-2026-illinois-crop-budgets.html", "label": "farmdoc daily, spring revision to 2026 Illinois crop budgets"}]}, "evidence": {"kind": "faceOff", "prompt": "On rented Illinois land in 2026, which crop projected the better return per acre?", "left": {"name": "Corn", "note": "Break-even near $4.80 a bushel"}, "right": {"name": "Soybeans", "note": "Small positive projected return"}, "correctIndex": 1, "explanation": "Corn projected a loss of $45 to $53 an acre at $4.50. Soybeans showed a small positive return."}, "numbers": {"kind": "numberSense", "prompt": "At the high end of the range, how many dollars per acre might rented corn lose?", "min": 0, "max": 120, "value": 53, "unit": "$", "explanation": "About $53 an acre at the high end; $45 at the low end."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You advise the farmer as an extension intern. He asks what to plant on the rented 80.", "prompt": "What do you suggest he weigh first?", "options": ["Which crop looks better at harvest", "Projected return per acre for each crop", "Which crop his father planted"], "correctIndex": 1, "consequences": ["Looks do not change returns.", "It follows the budget, which favored soybeans.", "Tradition does not set this year's prices."], "explanation": "The budget showed soybeans ahead per acre this year. Return per acre leads the decision."}, "proReasoning": "Advisors lead with the acre budget, then add rotation and risk.", "commonMistake": "Letting habit pick the crop.", "mentalModel": "Return per acre leads."}, "invest": {"call": {"kind": "theCall", "situation": "You sell corn seed in Illinois. Budgets favor soybeans on rented land this year.", "prompt": "What do you expect for your sales?", "options": ["Corn seed sales jump this year", "No change, since farmers never switch", "Some acres shift away from corn"], "correctIndex": 2, "consequences": ["Weaker corn returns cut demand for corn seed.", "Farmers do shift acres when budgets change.", "Farmers move acres toward the crop that pays."], "explanation": "When soybeans project better returns, farmers shift some acres. The budget shapes the field."}, "proReasoning": "Input sellers watch crop budgets to forecast acres. Budgets move demand.", "commonMistake": "Assuming acreage is fixed from year to year.", "mentalModel": "Budgets move acres."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a crop choice tool for farmers like this one.", "prompt": "What must it show?", "options": ["Return per acre for each crop", "A gallery of photos of each crop at harvest", "A detailed history of corn in Illinois"], "correctIndex": 0, "consequences": ["It answers the question farmers actually ask.", "Photos do not help choose a crop.", "History does not set this year's returns."], "explanation": "The choice comes down to dollars per acre. A tool should put those side by side."}, "proReasoning": "Founders make the decision visible: each option and its return per acre.", "commonMistake": "Adding content that does not change the decision.", "mentalModel": "Show options side by side."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend notices a neighbor switched from corn to soybeans and asks why.", "prompt": "What is the most likely reason?", "options": ["Corn was banned on rented land this year", "Soybeans paid better per acre", "Soybeans need no work or inputs at all"], "correctIndex": 1, "consequences": ["No such ban exists.", "The 2026 budgets favored soybeans on rented acres.", "Soybeans still take work and money."], "explanation": "When one crop pays better per acre, farmers shift some fields toward it."}, "proReasoning": "Crop switches usually follow the per-acre numbers.", "commonMistake": "Seeing a crop change as a whim.", "mentalModel": "Fields follow the budget."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a6cc23b253ba$ml$]::text[]),
($ml$3b2ee4cc-bc11-51e1-8c71-40fb38aea799$ml$::uuid, $ml$agtech$ml$, 8, 1, $ml${"id": "agtech-d8-c1", "title": "Anhydrous at $977 a ton", "lessonTitle": "Where a corn acre's money goes", "slot": 1, "type": "apply", "brief": {"headline": "In late September 2026, anhydrous fertilizer averaged $977 a ton at US retailers, 25% more than a year earlier. All eight major fertilizers cost more than a year before.", "kicker": "Apply the cost lines: which crop feels this most?", "fullText": "DTN tracks retail fertilizer prices each week. In the week of September 21 to 25, 2026, anhydrous averaged $977 a ton, up 6% in a month and 25% in a year. Urea was $675, up 9% in a year. All eight major fertilizers were higher than a year earlier.\n\nDay 8 showed why this matters: on top central Illinois land, variable cash costs such as fertilizer, seed and chemicals made up 47% of corn's cost in 2025. Corn uses far more nitrogen than soybeans.", "sources": [{"url": "https://www.dtnpf.com/agriculture/web/ag/news/article/2026/09/30/anhydrous-leads-fertilizer-prices-25", "label": "DTN retail fertilizer trends, Sept 2026"}, {"url": "https://farmdocdaily.illinois.edu/2026/04/cost-to-produce-corn-and-soybeans-in-illinois-2025.html", "label": "farmdoc daily, cost to produce corn and soybeans in Illinois, 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which crop does a 25% jump in nitrogen fertilizer hit harder?", "left": {"name": "Corn", "note": "Needs heavy nitrogen each year"}, "right": {"name": "Soybeans", "note": "Lower variable costs per acre"}, "correctIndex": 0, "explanation": "Corn depends on nitrogen, and its variable costs are higher. Fertilizer jumps hit corn hardest."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did anhydrous prices rise from a year earlier?", "min": 0, "max": 60, "value": 25, "unit": "%", "explanation": "25%, to an average of $977 a ton."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a fertilizer retailer. They ask what a 25% rise in anhydrous means for customers.", "prompt": "Which answer shows you know the farm budget?", "options": ["Corn growers, in their biggest cost line", "Farmers barely notice fertilizer price swings", "Soybean growers take the hardest hit of all"], "correctIndex": 0, "consequences": ["Variable costs are nearly half of corn's cost.", "Fertilizer is a major cost on corn acres.", "Soybeans use far less nitrogen than corn."], "explanation": "Fertilizer sits in the biggest cost line of a corn acre. Price jumps go straight to the bottom line."}, "proReasoning": "Connect the price move to the customer's biggest cost line. That shows you know their budget.", "commonMistake": "Talking about the product without its weight in the farm budget.", "mentalModel": "Link price moves to the big cost line."}, "invest": {"call": {"kind": "theCall", "situation": "Fertilizer prices are up across the board. You hold a fertilizer maker and a corn ethanol plant.", "prompt": "Which business benefits from higher fertilizer prices?", "options": ["Neither one", "The fertilizer maker", "The ethanol plant"], "correctIndex": 1, "consequences": ["One of them sells the product that rose.", "Higher prices raise its revenue per ton.", "It buys corn, not fertilizer."], "explanation": "A rise in fertilizer prices is revenue for its maker and a cost for corn growers."}, "proReasoning": "Investors see one company's cost as another's revenue. Map who sits on each side.", "commonMistake": "Treating a price rise as bad for the whole sector.", "mentalModel": "Your cost is someone's revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Nitrogen is up 25%. Your startup helps farms apply fertilizer more precisely.", "prompt": "How do you pitch it this fall?", "options": ["Use more fertilizer for bigger yields", "Switch to a new tractor brand", "Save on your costliest input as prices rise"], "correctIndex": 2, "consequences": ["More fertilizer adds to the cost spike.", "Tractors are a separate decision.", "Rising prices make every pound saved worth more."], "explanation": "Rising prices raise the value of savings. Precision tools sell best when inputs get expensive."}, "proReasoning": "Founders time pitches to cost spikes. Savings are worth most when prices jump.", "commonMistake": "Ignoring price swings that change the value of your product.", "mentalModel": "Price spikes raise the value of savings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why fertilizer prices matter to the price of corn chips.", "prompt": "What's the link?", "options": ["Fertilizer is a big corn cost", "Chips are partly made from fertilizer", "Fertilizer is added to chips as salt"], "correctIndex": 0, "consequences": ["Higher growing costs pressure corn farms.", "Chips are made from corn, not fertilizer.", "Fertilizer is used on fields, not in food."], "explanation": "Fertilizer is part of corn's biggest cost line. It affects farm margins before corn becomes food."}, "proReasoning": "Trace a food back to its farm costs. Inputs shape farm margins long before the store.", "commonMistake": "Linking farm inputs directly to shelf prices without the steps between.", "mentalModel": "Inputs shape farm margins first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f3802816929f$ml$]::text[]),
($ml$64a0e6d0-a63e-570e-8dee-80e53f5f0c01$ml$::uuid, $ml$agtech$ml$, 8, 2, $ml${"id": "agtech-d8-c2", "title": "Why fertilizer forecasts scare farmers", "lessonTitle": "Where a corn acre's money goes", "slot": 2, "type": "connect", "brief": {"headline": "USDA forecast fertilizer costs up 15.3% in 2026. On top Illinois land, variable cash costs like fertilizer and seed were already 47% of a corn acre's cost.", "kicker": "Connect day 4 and day 8: rising costs hit the biggest line.", "fullText": "Day 4 showed costs climbing: USDA forecast fertilizer costs to jump 15.3% in 2026 and total production costs to rise 4.5%.\n\nDay 8 shows where that lands. Growing an acre of corn on high-quality central Illinois land cost $1,216 in 2025, counting every economic cost. Across Illinois, variable cash costs such as fertilizer, seed and chemicals were 47% of corn's cost, other non-land costs 30%, and land 23%. Soybeans cost $910 an acre on the same land.", "sources": [{"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/farm-sector-income-forecast", "label": "USDA ERS, farm sector income forecast"}, {"url": "https://farmdocdaily.illinois.edu/2026/04/cost-to-produce-corn-and-soybeans-in-illinois-2025.html", "label": "farmdoc daily, cost to produce corn and soybeans in Illinois, 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each cost into its line on a corn acre.", "buckets": ["Variable cash", "Other non-land", "Land"], "items": [{"text": "Fertilizer", "bucket": 0}, {"text": "Seed", "bucket": 0}, {"text": "Machinery and overhead", "bucket": 1}, {"text": "Rent or land cost", "bucket": 2}], "explanation": "Fertilizer and seed are variable cash costs, 47% of the total. Machinery is non-land, and rent is the land cost."}, "numbers": {"kind": "numberSense", "prompt": "What did an acre of corn cost on top central Illinois land in 2025, in thousands of dollars?", "min": 0, "max": 3, "value": 1.2, "unit": "K", "explanation": "About $1,216, or 1.2K, counting every economic cost. Soybeans cost $910."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A farm lender asks which cost line it should watch when fertilizer forecasts jump.", "prompt": "What do you answer?", "options": ["Office supplies and phone bills on the farm", "Variable cash costs, near half the total", "Land costs, which change every single week"], "correctIndex": 1, "consequences": ["They are a tiny cost.", "Fertilizer sits in the 47% line.", "Land costs move slowly, not weekly."], "explanation": "Fertilizer is part of variable cash costs, the biggest line on a corn acre."}, "proReasoning": "Point lenders to the biggest and most volatile line. For corn, that is variable cash costs.", "commonMistake": "Spreading attention evenly across lines of very different sizes.", "mentalModel": "Watch the biggest, most volatile line."}, "invest": {"call": {"kind": "theCall", "situation": "You own farmland rented to corn and soybean growers. Fertilizer is forecast up 15.3%.", "prompt": "Which tenants feel it more?", "options": ["Soybean growers, who plant more acres", "Both feel it about equally", "Corn growers, with higher costs"], "correctIndex": 2, "consequences": ["Soybeans cost about $300 less an acre.", "Corn relies far more on nitrogen.", "Corn's variable costs are much higher."], "explanation": "Corn spends more on fertilizer per acre. Cost spikes squeeze corn tenants hardest."}, "proReasoning": "Landowners map cost spikes onto tenants' crops. Corn-heavy tenants carry more input risk.", "commonMistake": "Treating all row crops as equally exposed to input prices.", "mentalModel": "Corn carries the input risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could cut 5% from land costs or 5% from variable cash costs.", "prompt": "Which saves a corn farmer more?", "options": ["Variable cash costs, 47%", "Land costs, 23%", "Both save the same"], "correctIndex": 0, "consequences": ["5% of the largest line is the biggest saving.", "The land line is less than half as big.", "The lines differ in size."], "explanation": "The same percent saving is worth more on a bigger line. Variable cash costs are 47% of corn's cost."}, "proReasoning": "Founders aim at the biggest line. A small cut there beats a big cut on a small one.", "commonMistake": "Chasing savings in a small cost line.", "mentalModel": "Aim at the biggest line."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks land is the biggest cost of growing corn.", "prompt": "What do the numbers show?", "options": ["Labor is the only cost that matters", "Inputs like fertilizer cost more", "Land is more than half of the cost"], "correctIndex": 1, "consequences": ["Labor is part of a wider cost line.", "Variable cash costs were 47%; land was 23%.", "Land was about a quarter of the cost."], "explanation": "Variable cash costs like fertilizer and seed made up 47% of corn's cost. Land was 23%."}, "proReasoning": "Check the cost breakdown before guessing the biggest line.", "commonMistake": "Assuming the most visible asset is the biggest cost.", "mentalModel": "Inputs outweigh land on a corn acre."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bd434b02db3d$ml$]::text[]),
($ml$d2f7906e-8fbc-5afb-bb63-c17f6b68652f$ml$::uuid, $ml$agtech$ml$, 8, 3, $ml${"id": "agtech-d8-c3", "title": "Where to cut $50 an acre", "lessonTitle": "Where a corn acre's money goes", "slot": 3, "type": "decide", "brief": {"headline": "In 2025 an acre of corn on top central Illinois land cost $1,216. Statewide, corn cost about $5.16 a bushel on a 230-bushel yield. You must find savings next year.", "kicker": "Decide: which cost line do you go after?", "fullText": "Across Illinois, variable cash costs like fertilizer, seed and chemicals were 47% of corn's cost in 2025, other non-land costs 30%, and land 23%. Statewide, corn cost about $5.16 a bushel on a 230-bushel yield, and higher yields spread costs over more bushels.\n\nYou farm corn and need to cut about $50 an acre. The rule from day 8: in crop farming, the biggest savings hide in the biggest cost line.", "sources": [{"url": "https://farmdocdaily.illinois.edu/2026/04/cost-to-produce-corn-and-soybeans-in-illinois-2025.html", "label": "farmdoc daily, cost to produce corn and soybeans in Illinois, 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Besides cutting costs, what else lowers the cost per bushel?", "options": ["Planting much later than usual in spring", "Raising yield on the same acres", "Paying more rent for the very same field"], "correctIndex": 1, "explanation": "Cost per bushel is cost per acre divided by yield. More bushels on the same acre lower it."}, "numbers": {"kind": "numberSense", "prompt": "What was the statewide cost to grow a bushel of Illinois corn in 2025, in dollars?", "min": 0, "max": 12, "value": 5.2, "unit": "$", "explanation": "About $5.16 a bushel on a 230-bushel yield."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the farm's new operations hire. The owner asks where to look for $50 an acre.", "prompt": "Where do you start?", "options": ["The phone and internet bills", "New paint for the old barn", "Fertilizer, seed and chemicals"], "correctIndex": 2, "consequences": ["Too small to reach $50 an acre.", "Not a meaningful cost per acre.", "It is the 47% line, where savings are largest."], "explanation": "Variable cash costs are nearly half of corn's cost. That is where $50 an acre can be found."}, "proReasoning": "Start where the money is. Nearly half of corn's cost sits in inputs.", "commonMistake": "Spending effort on small costs first.", "mentalModel": "Start where the money is."}, "invest": {"call": {"kind": "theCall", "situation": "You can fund one of two farm tools: one cuts input use, one trims office costs.", "prompt": "Which has the bigger market?", "options": ["The input-saving tool", "The office-cost tool", "Both are about the same"], "correctIndex": 0, "consequences": ["Inputs are the largest cost on corn acres.", "Office costs are small per acre.", "The cost lines differ greatly."], "explanation": "A tool that cuts the largest cost line addresses far more spending."}, "proReasoning": "Investors size a product by the cost line it attacks. Inputs dwarf overhead.", "commonMistake": "Funding a tool that targets a small line.", "mentalModel": "Size by the cost line."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup can raise yields 5% or cut seed costs 5%. Corn costs $5.16 a bushel.", "prompt": "How do you show farmers the value of higher yield?", "options": ["As more work at harvest", "As a lower cost per bushel", "As a prettier field"], "correctIndex": 1, "consequences": ["That frames it as a burden.", "More bushels spread the same costs further.", "Looks do not lower costs."], "explanation": "Higher yield spreads costs over more bushels, which lowers cost per bushel."}, "proReasoning": "Founders translate yield gains into cost per bushel, a number farmers track.", "commonMistake": "Selling yield without its effect on unit cost.", "mentalModel": "Yield lowers cost per bushel."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a farm with the same costs can get cheaper per bushel.", "prompt": "How?", "options": ["By selling each bushel for less", "By planting fewer acres", "By growing more bushels on each acre"], "correctIndex": 2, "consequences": ["That lowers revenue, not cost.", "Fewer acres do not lower cost per bushel.", "Same costs over more bushels cost less each."], "explanation": "Cost per bushel falls when yield rises on the same costs."}, "proReasoning": "Unit cost is total cost divided by output. Raise output and the unit cost falls.", "commonMistake": "Thinking only cost cuts lower unit costs.", "mentalModel": "More output, lower unit cost."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:779ec2bd98ab$ml$]::text[]),
($ml$8dfa48c5-84de-5ae2-9ca2-0a22ba408109$ml$::uuid, $ml$agtech$ml$, 9, 1, $ml${"id": "agtech-d9-c1", "title": "Colorado's tractor repair law", "lessonTitle": "Who gets to fix the tractor", "slot": 1, "type": "apply", "brief": {"headline": "In April 2023 Colorado became the first state to give farmers a right to repair their equipment. Manufacturers must sell tools, parts and digital access to farmers and independent shops.", "kicker": "Apply the power map: who loses control of repairs?", "fullText": "Governor Jared Polis signed House Bill 1011 on April 25, 2023, effective January 1, 2024. Farmers testified about the cost of waiting for dealers. One paid $950 for a technician to enter a code that got his tractor running again, two days after paying $8,500 for repairs.\n\nManufacturers opposed the bill, warning farmers could tamper with emissions controls; sponsors kept those changes illegal. In January 2023 Deere had signed a private agreement with the American Farm Bureau Federation, which had no enforcement provision.", "sources": [{"url": "https://www.coloradopolitics.com/2023/04/25/colorado-becomes-first-state-to-establish-right-to-repair-agricultural-equipment-b95ee35a-e39a-11ed-a375-6324da7c42fa", "label": "Colorado Politics, first state right to repair for farm equipment, Apr 2023"}, {"url": "https://iowacapitaldispatch.com/2025/01/22/ftc-sues-john-deere-over-right-to-repair/", "label": "Iowa Capital Dispatch, FTC sues Deere over right to repair"}]}, "evidence": {"kind": "sortSignal", "prompt": "Who gains and who loses under the Colorado law?", "buckets": ["Gains", "Loses some control"], "items": [{"text": "Farmers who fix their own machines", "bucket": 0}, {"text": "Independent repair shops", "bucket": 0}, {"text": "Dealer service departments", "bucket": 1}, {"text": "Manufacturers that kept tools for dealers", "bucket": 1}], "explanation": "The law opens tools and software to farmers and independent shops. Dealers lose their exclusive hold on repairs."}, "numbers": {"kind": "numberSense", "prompt": "How much did one farmer pay a technician just to enter a software code, in dollars?", "min": 0, "max": 2400, "value": 950, "unit": "$", "explanation": "$950, two days after paying $8,500 for repairs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a farm equipment dealer in Colorado. They ask how the law changes their business.", "prompt": "Which answer is accurate?", "options": ["Farmers must now buy repairs from dealers", "Repairs face new competition from independents", "Dealers can no longer sell tractors"], "correctIndex": 1, "consequences": ["The law does the opposite.", "Independent shops can now get the tools and software.", "Sales are untouched; repairs are what open up."], "explanation": "The law makes manufacturers sell repair tools to farmers and independent shops, so dealers compete for repairs."}, "proReasoning": "Name what changes precisely: repairs open to competition, sales do not.", "commonMistake": "Overstating the law as a ban on dealers.", "mentalModel": "Open tools, open repair market."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a dealer chain that earns a big share of profit from service. More states may copy Colorado.", "prompt": "What risk do you weigh?", "options": ["Higher tractor prices from the law", "More farmers buying new machines", "Lower service margins as repairs open up"], "correctIndex": 2, "consequences": ["The law targets repair, not prices.", "The law does not push new purchases.", "Competition from independents can squeeze service profit."], "explanation": "Dealer service departments lose exclusivity. If more states follow, service margins face pressure."}, "proReasoning": "Investors find where a law moves profit. Here it moves repair work away from dealers.", "commonMistake": "Ignoring a state law that could spread.", "mentalModel": "Follow where the law moves profit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Colorado now requires access to repair tools. Your startup could serve independent shops.", "prompt": "What product fits the new opening?", "options": ["Diagnostic tools for independent shops", "A new tractor brand to rival Deere", "A loyalty program for big dealers"], "correctIndex": 0, "consequences": ["Shops now need the skills and tools to compete.", "Building tractors is a far bigger bet.", "It works against the shift the law creates."], "explanation": "When repair opens up, independent shops need tools and training to take the work."}, "proReasoning": "Founders build for whoever a new law empowers. Here that is independent repair.", "commonMistake": "Building for the side that just lost its advantage.", "mentalModel": "Build for the newly empowered."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why farmers could not just fix their own tractors before.", "prompt": "What was the obstacle?", "options": ["Farmers were banned from owning tools", "Repairs needed dealer-only software", "Tractors have almost no moving parts"], "correctIndex": 1, "consequences": ["No such ban existed.", "Without the software, many repairs could not be finished.", "Tractors have plenty of moving parts."], "explanation": "Modern tractors run on software. Without the diagnostic tools, a farmer could not complete many repairs."}, "proReasoning": "In modern machines, software can control who repairs them.", "commonMistake": "Thinking repairs are only about wrenches and parts.", "mentalModel": "Software controls repair."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bbb8f49ca7b3$ml$]::text[]),
($ml$8b6c509c-d421-5c24-9926-ded887b2f48b$ml$::uuid, $ml$agtech$ml$, 9, 2, $ml${"id": "agtech-d9-c2", "title": "Power over seeds, power over repairs", "lessonTitle": "Who gets to fix the tractor", "slot": 2, "type": "connect", "brief": {"headline": "Two seed companies supplied 72% of US corn acres in 2018 to 2020. In January 2025 the FTC sued Deere, alleging it kept repair tools for its dealers.", "kicker": "Connect day 3 and day 9: control is another form of power.", "fullText": "Day 3 showed power through concentration: two seed companies held 72% of corn acres, and four packers handled 85% of steer and heifer slaughter.\n\nDay 9 shows power through control. In January 2025 the FTC sued Deere, alleging it made its electronic diagnostic and repair tools available only to licensed dealers. Minnesota and Illinois joined the case. Deere called the complaint \"flagrant misrepresentations of the facts.\" Farmers said waiting for a dealer costs time, and time matters at harvest.", "sources": [{"url": "https://ers.usda.gov/webdocs/publications/106795/eib-256_summary.pdf?v=4878.9", "label": "USDA ERS, concentration and competition report"}, {"url": "https://iowacapitaldispatch.com/2025/01/22/ftc-sues-john-deere-over-right-to-repair/", "label": "Iowa Capital Dispatch, FTC sues Deere over right to repair"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What do seed concentration and dealer-only repair tools have in common?", "options": ["Both lower the prices farmers pay", "Both were set up by the FTC itself", "Both limit farmers' choices"], "correctIndex": 2, "explanation": "Few seed sellers and dealer-only repairs both leave farmers with fewer places to go."}, "numbers": {"kind": "numberSense", "prompt": "How many states joined the FTC case against Deere?", "min": 0, "max": 10, "value": 2, "unit": "states", "explanation": "Two: Minnesota and Illinois."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A policy group interviews you. They ask what the Deere case and seed concentration share.", "prompt": "What is your answer?", "options": ["Both are mainly about food safety", "Both mainly concern export rules", "Farmers rely on a few firms"], "correctIndex": 2, "consequences": ["Neither case is about food safety.", "Neither is an export issue.", "Concentration and control both limit choice."], "explanation": "Seed and repair are both areas where farmers rely on a few companies, which shapes their bargaining power."}, "proReasoning": "Spot the common thread: fewer options for the farmer, more power for the seller.", "commonMistake": "Treating each case as unrelated.", "mentalModel": "Fewer options, more seller power."}, "invest": {"call": {"kind": "theCall", "situation": "You compare an equipment maker facing the FTC suit with a seed company in a concentrated market.", "prompt": "What risk do they share?", "options": ["Regulators watch their power", "Falling demand for food", "A national shortage of farmland"], "correctIndex": 0, "consequences": ["Power over farmers draws antitrust attention.", "Food demand is steady.", "Farmland is not the shared issue."], "explanation": "Market power brings pricing strength and regulatory scrutiny, in seeds and in repair."}, "proReasoning": "Investors pair pricing power with regulatory risk. They tend to arrive together.", "commonMistake": "Valuing control without pricing in the scrutiny.", "mentalModel": "Power and scrutiny travel together."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers feel locked in on both seeds and repairs. You want to build something useful.", "prompt": "Which idea adds real choice?", "options": ["A tractor game for farm families", "An independent repair network", "A weekly newsletter on seed prices"], "correctIndex": 1, "consequences": ["Entertainment does not change choices.", "It gives farmers another place to get repairs.", "Information alone does not add suppliers."], "explanation": "Choice comes from new suppliers. An independent repair network is one."}, "proReasoning": "Founders add suppliers where farmers are locked in.", "commonMistake": "Selling information when the problem is a lack of options.", "mentalModel": "Add suppliers, add choice."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a lawsuit about tractor repairs matters to food.", "prompt": "What's the connection?", "options": ["Tractors are part of the food itself", "Repair costs set grocery prices", "Harvest delays can cost a crop"], "correctIndex": 2, "consequences": ["Tractors grow food; they are not in it.", "Grocery prices are set much later in the chain.", "Time matters at harvest; a broken machine waits."], "explanation": "Farmers said waiting for a dealer costs time, and time matters at harvest."}, "proReasoning": "Follow the delay. A day without a combine at harvest can cost real yield.", "commonMistake": "Thinking equipment rules are far from food.", "mentalModel": "Delays at harvest cost crops."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:775e819793ba$ml$]::text[]),
($ml$81c0ae14-d160-57b9-834f-842fddfe869d$ml$::uuid, $ml$agtech$ml$, 9, 3, $ml${"id": "agtech-d9-c3", "title": "New combine or a fixable old one", "lessonTitle": "Who gets to fix the tractor", "slot": 3, "type": "decide", "brief": {"headline": "The FTC alleged in 2025 that Deere kept its repair tools for dealers. You must replace a combine before harvest, and repair access is part of the choice.", "kicker": "Decide: what do you weigh when buying a machine?", "fullText": "Modern tractors and combines run on software, so many repairs need diagnostic tools. The FTC's January 2025 suit alleged Deere made those tools available only to licensed dealers, and asked a court to make Deere share them with farmers and independent shops. Deere rejected the claims.\n\nYou must replace your combine before harvest. A new model has the latest software. An older model is cheaper and easier to fix yourself. The rule from day 9: power sits with whoever controls the software and repair tools.", "sources": [{"url": "https://iowacapitaldispatch.com/2025/01/22/ftc-sues-john-deere-over-right-to-repair/", "label": "Iowa Capital Dispatch, FTC sues Deere over right to repair"}, {"url": "https://www.coloradopolitics.com/2023/04/25/colorado-becomes-first-state-to-establish-right-to-repair-agricultural-equipment-b95ee35a-e39a-11ed-a375-6324da7c42fa", "label": "Colorado Politics, first state right to repair for farm equipment, Apr 2023"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Many modern repairs need diagnostic software.", "The FTC asked for repair tools to be shared.", "Deere agreed with the FTC complaint."], "fakeIndex": 2, "explanation": "Deere called the complaint \"flagrant misrepresentations of the facts.\" It did not agree."}, "numbers": {"kind": "numberSense", "prompt": "One Colorado farmer paid for repairs before a $950 code fee. How much, in thousands of dollars?", "min": 0, "max": 20, "value": 8.5, "unit": "K", "explanation": "$8,500, and two days later $950 more just to have a code entered."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are an equipment advisor. The farmer asks what to check beyond price.", "prompt": "What do you add to the list?", "options": ["Who can repair it, and how fast", "The paint color options offered", "How comfortable the cab seat is"], "correctIndex": 0, "consequences": ["Repair access decides downtime at harvest.", "Color does not affect harvest.", "Comfort matters less than uptime."], "explanation": "A machine that only a distant dealer can fix risks costly delays at harvest."}, "proReasoning": "Advisors price downtime into the purchase. Repair access is part of the real cost.", "commonMistake": "Comparing machines on sticker price alone.", "mentalModel": "Price in the downtime."}, "invest": {"call": {"kind": "theCall", "situation": "You value used combines for a lender. Repair access is in the news.", "prompt": "Which feature could raise resale value?", "options": ["A short dealer warranty", "Easy repair without dealers", "A rare factory paint finish"], "correctIndex": 1, "consequences": ["Short warranties do not raise value.", "Farmers value machines they can fix themselves.", "Paint does not change usefulness."], "explanation": "If repair access is limited, machines that are easy to fix become more valuable."}, "proReasoning": "Lenders track what buyers value. Repairability can hold resale value.", "commonMistake": "Valuing machines only by age and hours.", "mentalModel": "Repairability holds value."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers weigh repair access when buying machines. Your startup tracks machine data.", "prompt": "What could you offer?", "options": ["A color picker for each machine", "An online combine fan club", "A repairability score for each model"], "correctIndex": 2, "consequences": ["Color does not affect the choice.", "It does not inform the purchase.", "It helps farmers weigh downtime risk."], "explanation": "A clear repairability score helps farmers price downtime into their choice."}, "proReasoning": "Founders turn a hidden cost into a visible number.", "commonMistake": "Building features that do not touch the decision.", "mentalModel": "Make hidden costs visible."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why some farmers prefer older machines.", "prompt": "Which reason fits day 9?", "options": ["They can fix them on their own", "Older machines grow more crops per acre", "New machines cannot be insured at all"], "correctIndex": 0, "consequences": ["Older, simpler machines are easier to repair.", "Machines do not grow crops faster by age.", "New machines can be insured."], "explanation": "Less software can mean fewer locked repairs and less waiting at harvest."}, "proReasoning": "Simplicity can be a feature when repairs are controlled.", "commonMistake": "Assuming newer is always better on a farm.", "mentalModel": "Simple can mean fixable."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9f1d77ad6a4c$ml$]::text[]),
($ml$4324aa2f-c681-5759-a3b4-5a3406ceef99$ml$::uuid, $ml$agtech$ml$, 10, 1, $ml${"id": "agtech-d10-c1", "title": "The forecast that sank corn", "lessonTitle": "A record crop, a weaker price", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025 USDA raised its corn forecast by 1 billion bushels to a record 16.7 billion. In the same report it cut the expected corn price by 30 cents to $3.90 a bushel.", "kicker": "Apply the lesson: why does a bigger crop lower the price?", "fullText": "The August 2025 World Agricultural Supply and Demand Estimates forecast corn production at a record 16.7 billion bushels, up 1 billion from the month before. The expected yield rose 7.8 bushels to a record 188.8 bushels per acre.\n\nThe same report lowered the season-average price farmers would receive by 30 cents to $3.90 a bushel. A bigger harvest adds supply; unless demand keeps up, each bushel is worth less.", "sources": [{"url": "https://www.agproud.com/articles/62024-lowered-corn-price-to-390-per-bushel", "label": "Ag Proud, August 2025 WASDE lowers corn price to $3.90"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the record crop story in order.", "steps": ["Good weather lifts yields across the Corn Belt", "USDA raises its production forecast", "Traders expect more supply than demand", "The expected price per bushel falls"], "explanation": "More supply with steady demand pushes prices down. A record crop can mean less money per bushel."}, "numbers": {"kind": "numberSense", "prompt": "By how many cents did USDA cut its expected corn price in August 2025?", "min": 0, "max": 80, "value": 30, "unit": "cents", "explanation": "30 cents, to $3.90 a bushel."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a grain merchandiser. They ask how a record crop forecast hits the market.", "prompt": "Which answer is right?", "options": ["A record crop always lifts the price per bushel", "Forecasts never move grain markets at all", "More supply pushes the price per bushel down"], "correctIndex": 2, "consequences": ["Bigger supply usually weakens the price.", "This forecast moved the expected price by 30 cents.", "The same report cut the price to $3.90."], "explanation": "USDA raised the crop by a billion bushels and cut the price 30 cents in one report."}, "proReasoning": "Link supply forecasts to price in one line. Merchandisers think in supply and demand.", "commonMistake": "Assuming more production means more revenue.", "mentalModel": "More supply, weaker price."}, "invest": {"call": {"kind": "theCall", "situation": "You hold an ethanol producer that buys corn. USDA forecasts a record crop.", "prompt": "How does the forecast affect it?", "options": ["Cheaper corn lowers its biggest input cost", "It raises the plant's corn costs sharply", "Ethanol makers do not buy any corn"], "correctIndex": 0, "consequences": ["A lower corn price helps a corn buyer.", "A record crop points to cheaper corn.", "Corn is the main input for US ethanol."], "explanation": "A falling corn price hurts growers but helps buyers like ethanol plants and feedlots."}, "proReasoning": "Investors flip the lens: the farmer's weak price is the buyer's cheap input.", "commonMistake": "Treating a crop price drop as bad for everyone.", "mentalModel": "One side's low price is the other's savings."}, "build_startup": {"call": {"kind": "theCall", "situation": "Corn prices are falling with a record crop. Your startup serves corn growers.", "prompt": "Which product fits this moment?", "options": ["Ads promoting corn to shoppers", "Tools to find storage or better sale timing", "A plan to plant even more corn next year"], "correctIndex": 1, "consequences": ["Shopper ads barely move a national surplus.", "Growers need ways to avoid selling at the low.", "More corn adds to the surplus."], "explanation": "When a big crop weighs on price, growers look for storage and timing to sell better."}, "proReasoning": "Founders help customers through the price cycle, not against it.", "commonMistake": "Pushing more output into a glut.", "mentalModel": "Help them time the glut."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks a record harvest must be great news for farmers.", "prompt": "What's the catch?", "options": ["Record crops are always lost to rot", "Farmers are paid only for small crops", "Each bushel may be worth less"], "correctIndex": 2, "consequences": ["Most of the crop is stored or sold.", "Farmers are paid per bushel sold.", "The price forecast fell 30 cents with the bigger crop."], "explanation": "A bigger crop adds supply, and prices fall. More bushels can bring less per bushel."}, "proReasoning": "For commodities, ask what happens to price when everyone has a good year.", "commonMistake": "Judging a harvest by size alone.", "mentalModel": "A good year for all can lower the price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fe4fd7061874$ml$]::text[]),
($ml$9e4a56ba-7a62-51ed-a92d-4dea0fc63749$ml$::uuid, $ml$agtech$ml$, 10, 2, $ml${"id": "agtech-d10-c2", "title": "Record yield, still underwater", "lessonTitle": "A record crop, a weaker price", "slot": 2, "type": "connect", "brief": {"headline": "US corn yielded a record 186.5 bushels per acre in 2025. Yet in 2026 Illinois corn on rented land needed about $4.80 a bushel to break even, above the $4.50 assumed.", "kicker": "Connect day 7 and day 10: yield helps, price decides.", "fullText": "Day 7 showed the acre P&L: revenue is yield times price, and rented Illinois corn was projected to lose $45 to $53 an acre at $4.50 a bushel, with break-even near $4.80.\n\nDay 10 shows the market behind that price. US farmers grew a record 17.0 billion bushels of corn in 2025, up 14%, on a record yield of 186.5 bushels per acre. Harvested acres rose 10% to 91.3 million. A record crop adds supply and pressures price.", "sources": [{"url": "https://farmdocdaily.illinois.edu/2026/05/spring-revision-to-2026-illinois-crop-budgets.html", "label": "farmdoc daily, spring revision to 2026 Illinois crop budgets"}, {"url": "https://www.rfdtv.com/record-corn-crop-leads-mixed-2025-u-s-production?p=151", "label": "RFD-TV, record corn crop leads 2025 US production"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Revenue per acre is yield times price. What happens if both yield and supply hit records?", "options": ["Price stays fixed whatever the supply", "Higher yield may not offset the lower price", "Revenue per acre must rise a lot"], "correctIndex": 1, "explanation": "Every farm's good yield adds to national supply. The lower price can cancel the gain on each acre."}, "numbers": {"kind": "numberSense", "prompt": "How many billion bushels of corn did US farmers grow in 2025?", "min": 0, "max": 30, "value": 17, "unit": "B", "explanation": "A record 17.0 billion bushels, up 14% from 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A farm lender asks you why a record yield did not fix farm budgets.", "prompt": "What is the cleanest answer?", "options": ["National supply rose too, pulling price down", "Yields were not counted in the budgets", "Budgets ignore price completely"], "correctIndex": 0, "consequences": ["Revenue depends on price as well as yield.", "Budgets use yields directly.", "Price is half of revenue per acre."], "explanation": "Revenue per acre is yield times price. A record national crop pulls price down."}, "proReasoning": "Use both halves of the revenue formula. Yield and price move together in a big year.", "commonMistake": "Talking about yield without price.", "mentalModel": "Revenue is yield times price."}, "invest": {"call": {"kind": "theCall", "situation": "Corn acres rose 10% while soybean acres fell 7%. You track crop prices.", "prompt": "Which price faces more supply pressure?", "options": ["Neither, since acres do not move prices", "Corn, after more acres and record yield", "Soybeans, after fewer acres planted"], "correctIndex": 1, "consequences": ["Acres feed directly into supply.", "More acres and a record yield mean a big supply.", "Soybean output actually fell 3%."], "explanation": "Corn got both more acres and a record yield. That much supply weighs on its price."}, "proReasoning": "Investors add acres and yield to read supply. Both pointed up for corn in 2025.", "commonMistake": "Watching yield alone and missing the acreage shift.", "mentalModel": "Acres times yield is supply."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells yield-boosting software. Farmers say yield is not their problem this year.", "prompt": "How do you adjust your pitch?", "options": ["Promise even bigger yields next year", "Stop selling to corn growers for good", "Show savings per bushel, not more bushels"], "correctIndex": 2, "consequences": ["More bushels add to the glut.", "Corn growers still need help with margins.", "Lower cost per bushel helps at a low price."], "explanation": "When price is the problem, cost per bushel matters more than extra bushels."}, "proReasoning": "Founders listen to which half of the formula hurts. This year it is price, so sell cost savings.", "commonMistake": "Pushing yield when the market already has too much.", "mentalModel": "Sell to the half that hurts."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how farmers can grow record crops and still lose money.", "prompt": "What do you say?", "options": ["The price per bushel fell below costs", "Farmers lost most of the record crop", "Record crops cost nothing to grow"], "correctIndex": 0, "consequences": ["Rented corn needed $4.80 but the budget assumed $4.50.", "The crop was harvested and counted.", "Costs stay high in good years too."], "explanation": "A record crop pushed prices down, and costs stayed high."}, "proReasoning": "A bigger harvest does not mean a better year if price falls below cost.", "commonMistake": "Equating a big crop with big profit.", "mentalModel": "Price below cost beats any yield."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7bb8d7866761$ml$]::text[]),
($ml$e27f12b8-0d8b-52f1-9adf-d7d5a49a16ab$ml$::uuid, $ml$agtech$ml$, 10, 3, $ml${"id": "agtech-d10-c3", "title": "Sell at harvest or store it", "lessonTitle": "A record crop, a weaker price", "slot": 3, "type": "decide", "brief": {"headline": "US farmers harvested a record 17.0 billion bushels of corn in 2025. You have a bin full of corn and prices are weak after the record crop.", "kicker": "Decide: sell now, or store and wait?", "fullText": "In 2025 US corn production hit a record 17.0 billion bushels, up 14%, on a record yield of 186.5 bushels per acre. Harvested acres rose 10% to 91.3 million as farmers shifted acres from soybeans to corn. A record crop adds supply, and unless demand keeps up, prices fall.\n\nYou have corn in your bin. You can sell at harvest or store it and sell later, paying storage and interest while you wait.", "sources": [{"url": "https://www.rfdtv.com/record-corn-crop-leads-mixed-2025-u-s-production?p=151", "label": "RFD-TV, record corn crop leads 2025 US production"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each point favor selling now or storing?", "buckets": ["Sell now", "Store and wait"], "items": [{"text": "You need cash to pay a loan this month", "bucket": 0}, {"text": "Storage and interest costs are high", "bucket": 0}, {"text": "Prices usually rise after harvest pressure eases", "bucket": 1}, {"text": "You have your own bins with space", "bucket": 1}], "explanation": "Cash needs and holding costs favor selling. Owned storage and a seasonal price recovery favor waiting."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did US corn production rise in 2025 from 2024?", "min": 0, "max": 40, "value": 14, "unit": "%", "explanation": "14%, to a record 17.0 billion bushels."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are a grain marketing advisor. A client asks whether to sell her corn at harvest.", "prompt": "What do you check first?", "options": ["Which buyer has the nicest office", "Her cash needs and the cost of storing", "What her neighbors did last year"], "correctIndex": 1, "consequences": ["Offices do not affect the price.", "They decide whether waiting can pay off.", "Last year's choices do not fit this market."], "explanation": "Storing makes sense only if the expected gain beats storage and interest, and she can wait for cash."}, "proReasoning": "Advisors weigh holding costs against expected gains, and check cash needs first.", "commonMistake": "Recommending storage without counting its cost.", "mentalModel": "Waiting must beat its cost."}, "invest": {"call": {"kind": "theCall", "situation": "After the record crop, many farmers want to store corn. You own grain bins and elevators.", "prompt": "What happens to demand for storage?", "options": ["It falls with lower prices", "It never changes year to year", "It rises with the big crop"], "correctIndex": 2, "consequences": ["Lower prices push more farmers to wait and store.", "Storage demand follows crop size.", "A record crop needs more space."], "explanation": "A record crop plus weak prices makes storage more valuable."}, "proReasoning": "Investors see storage as the winner of a glut. Space gains value when crops are big.", "commonMistake": "Missing that a glut helps whoever owns storage.", "mentalModel": "Gluts reward storage owners."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers ask when to sell their stored corn. Your startup has price and cost data.", "prompt": "What should the tool show?", "options": ["Gain from waiting, minus storage", "Yesterday's weather on the farm", "A guaranteed price for next spring"], "correctIndex": 0, "consequences": ["It frames the real trade-off.", "Weather does not set the sale decision.", "No tool can guarantee a future price."], "explanation": "The decision is whether waiting pays. Show the expected gain net of storage cost."}, "proReasoning": "Founders frame the trade-off honestly, without promising prices.", "commonMistake": "Promising certainty in a volatile market.", "mentalModel": "Show the net gain of waiting."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend sees huge piles of corn by an elevator and asks why.", "prompt": "What explains the piles?", "options": ["Farmers threw away their extra corn", "A record crop outgrew the bins", "Corn is grown right at the elevator"], "correctIndex": 1, "consequences": ["The corn is stored to be sold.", "17.0 billion bushels needed space somewhere.", "Elevators store grain; they do not grow it."], "explanation": "A record harvest can exceed bin space, so some corn waits in piles."}, "proReasoning": "Visible piles of grain are a sign of a big crop and weak prices.", "commonMistake": "Thinking stored grain is wasted grain.", "mentalModel": "Piles signal a glut."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:97dc5e99a0d6$ml$]::text[]),
($ml$b018d87a-dd0b-5c14-800d-c8c8a1e7d4c3$ml$::uuid, $ml$agtech$ml$, 11, 1, $ml${"id": "agtech-d11-c1", "title": "2024's $20 billion in crop losses", "lessonTitle": "Insurance on the harvest", "slot": 1, "type": "apply", "brief": {"headline": "Weather destroyed more than $20.3 billion of US crops and rangeland in 2024. Crop insurance covered $10.9 billion, leaving about $9.4 billion uninsured.", "kicker": "Apply the safety net: what did insurance catch, and what slipped?", "fullText": "The American Farm Bureau counted 2024 losses from drought, heat, wildfire, floods and hurricanes. Of more than $20.3 billion in losses, $10.9 billion was covered by USDA's Risk Management Agency programs as of February 2025, a bit over half.\n\nDrought, heat and wildfire caused over $11 billion, and only 47% of that was insured. Texas lost over $3.4 billion, including $1.8 billion in cotton. The rest fell outside policy limits or did not qualify.", "sources": [{"url": "https://www.fb.org/intel/markets/hurricanes-heat-and-hardship-counting-2024s-crop-losses", "label": "Farm Bureau, counting 2024's crop losses"}, {"url": "https://www.ers.usda.gov/topics/farm-practices-management/risk-management/crop-insurance-at-a-glance", "label": "USDA ERS, crop insurance at a glance"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false about 2024 crop losses. Tap it.", "statements": ["Insurance covered about half of the losses.", "Texas lost over $3.4 billion.", "Insurance covered nearly all drought losses."], "fakeIndex": 2, "explanation": "Only 47% of drought, heat and wildfire losses were insured. More than half fell outside coverage."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars of 2024 losses were covered by crop insurance?", "min": 0, "max": 30, "value": 10.9, "unit": "B", "explanation": "About $10.9 billion of more than $20.3 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a crop insurer. They ask what the 2024 losses say about coverage.", "prompt": "Which answer is most useful?", "options": ["Big gaps remain, especially for drought", "Insurance now covers nearly every loss", "Farmers lost almost nothing in 2024"], "correctIndex": 0, "consequences": ["About $9.4 billion of losses went uninsured.", "Only about half was covered.", "Losses topped $20.3 billion."], "explanation": "Insurance covered about half of 2024 losses, and less than half of drought losses."}, "proReasoning": "Point to the gap. A coverage gap is where an insurer can grow.", "commonMistake": "Assuming the safety net catches everything.", "mentalModel": "Find the coverage gap."}, "invest": {"call": {"kind": "theCall", "situation": "You lend to farms in Texas, which lost over $3.4 billion in 2024.", "prompt": "What do you check about your borrowers?", "options": ["How far each farm is from a big city", "How much of their losses was insured", "Whether they planted the newest seeds"], "correctIndex": 1, "consequences": ["Distance does not decide coverage.", "Uninsured losses hit repayment directly.", "Looks do not affect losses."], "explanation": "About $9.4 billion of 2024 losses were uninsured. Uninsured borrowers carry the most risk."}, "proReasoning": "Lenders check insurance before lending. Coverage decides who can repay after a disaster.", "commonMistake": "Assuming every farm is fully insured.", "mentalModel": "Coverage decides repayment."}, "build_startup": {"call": {"kind": "theCall", "situation": "Drought losses were only 47% insured in 2024. Your startup works on farm risk.", "prompt": "Where is the opportunity?", "options": ["Insurance for farms that already have full cover", "Weather apps with no link to cover", "Products for losses current policies miss"], "correctIndex": 2, "consequences": ["They do not need more of the same cover.", "Data alone does not pay for losses.", "That is where farmers lose money today."], "explanation": "The gap is drought and other losses outside policy limits. That is unmet need."}, "proReasoning": "Founders build where losses go uncovered. Gaps in the safety net are markets.", "commonMistake": "Selling what farmers already have.", "mentalModel": "Build in the gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend assumes crop insurance pays farmers back for any disaster.", "prompt": "What do the 2024 numbers show?", "options": ["It covered only about half the losses", "It covered every single loss", "Farmers were not insured at all"], "correctIndex": 0, "consequences": ["$10.9 billion of over $20.3 billion was covered.", "About $9.4 billion was uninsured.", "Most acres are enrolled in insurance."], "explanation": "Insurance is the main safety net, but about $9.4 billion of 2024 losses went uncovered."}, "proReasoning": "Safety nets have holes. Ask how much of a loss is actually covered.", "commonMistake": "Treating insurance as full protection.", "mentalModel": "Nets have holes."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:59ae4153aa1c$ml$]::text[]),
($ml$459d6b85-c648-5529-ba16-b477b6a86673$ml$::uuid, $ml$agtech$ml$, 11, 2, $ml${"id": "agtech-d11-c2", "title": "Two safety nets, one budget", "lessonTitle": "Insurance on the harvest", "slot": 2, "type": "connect", "brief": {"headline": "Direct farm payments are forecast at $47.4 billion in 2026. Separately, the government paid $10.4 billion in crop insurance premium subsidies in 2024.", "kicker": "Connect day 2 and day 11: payments and insurance both prop up income.", "fullText": "Day 2 showed direct government payments rising 69.8% to $47.4 billion in 2026, nearly a third of net farm income.\n\nDay 11 shows a second net. Federal crop insurance covered 543 million acres in 2024, with liability above $192 billion, and about 89% of the acreage of eight major field crops was enrolled. The government paid $10.4 billion in premium subsidies, and it cost $2.34 billion to deliver the policies through private insurers.", "sources": [{"url": "https://ers.usda.gov/topics/farm-economy/farm-sector-income-finances/highlights-from-the-farm-income-forecast", "label": "USDA ERS, farm income highlights"}, {"url": "https://www.ers.usda.gov/topics/farm-practices-management/risk-management/crop-insurance-at-a-glance", "label": "USDA ERS, crop insurance at a glance"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each a direct payment or part of crop insurance?", "buckets": ["Direct payment", "Crop insurance"], "items": [{"text": "Farm Bill commodity payments", "bucket": 0}, {"text": "Disaster aid checks", "bucket": 0}, {"text": "Premium subsidies on policies", "bucket": 1}, {"text": "Payouts when yields fall short", "bucket": 1}], "explanation": "Commodity and disaster payments come directly from the government. Insurance pays claims, with premiums subsidized."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars did the government pay in premium subsidies in 2024?", "min": 0, "max": 30, "value": 10.4, "unit": "B", "explanation": "$10.4 billion. Delivering the policies cost another $2.34 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A policy think tank asks you to describe the farm safety net in one line.", "prompt": "Which line is most complete?", "options": ["Higher grocery prices set by federal law", "Direct payments plus insurance", "Only disaster checks after big storms"], "correctIndex": 1, "consequences": ["The government does not set grocery prices.", "Both nets matter: $47.4 billion and $10.4 billion.", "Disaster aid is only one piece."], "explanation": "Farms rely on direct payments and on insurance with subsidized premiums."}, "proReasoning": "Name both nets and their scale. That shows you see the whole support system.", "commonMistake": "Describing only the most visible program.", "mentalModel": "Two nets: payments and insurance."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a private crop insurer. It sells policies under an agreement with USDA.", "prompt": "What supports its business?", "options": ["A ban on farmers buying other insurance", "Profits from selling the crops it insures", "Subsidized premiums for farmers"], "correctIndex": 2, "consequences": ["No such ban exists.", "Insurers sell policies, not crops.", "Subsidies make policies affordable, keeping 89% enrolled."], "explanation": "Premium subsidies keep enrollment high. Private insurers sell and service those policies."}, "proReasoning": "Investors see subsidies as demand support for insurers. Policy keeps the customer base large.", "commonMistake": "Ignoring how much the business depends on federal support.", "mentalModel": "Subsidies hold up demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to help farmers with both payments and insurance. Paperwork is heavy for each.", "prompt": "What product fits?", "options": ["One place for payments and policies", "A new crop for farmers to plant", "A tractor rental service for farms"], "correctIndex": 0, "consequences": ["It cuts work across both safety nets.", "It does not touch either program.", "It is unrelated to the safety net."], "explanation": "Farmers juggle two big programs. A tool that tracks both saves time."}, "proReasoning": "Founders simplify complex public programs. Combining two nets in one view saves real hours.", "commonMistake": "Solving one program's paperwork and ignoring the other.", "mentalModel": "Simplify the whole net."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if taxpayers really support farm income.", "prompt": "What do the figures show?", "options": ["Only through low taxes on food sales", "Yes, through payments and subsidies", "No, farms receive no public support"], "correctIndex": 1, "consequences": ["Food taxes are not the support channel.", "$47.4 billion in payments and $10.4 billion in subsidies.", "Both programs are large."], "explanation": "Taxpayers fund direct payments and much of crop insurance premiums."}, "proReasoning": "Look for support in more than one form. It often comes through insurance too.", "commonMistake": "Counting only direct checks.", "mentalModel": "Support comes in many forms."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:be3a700e91ce$ml$]::text[]),
($ml$ac646345-561c-5c6c-a468-03d71be77374$ml$::uuid, $ml$agtech$ml$, 11, 3, $ml${"id": "agtech-d11-c3", "title": "How much coverage to buy", "lessonTitle": "Insurance on the harvest", "slot": 3, "type": "decide", "brief": {"headline": "Federal crop insurance covered 543 million acres in 2024, and about 89% of major field crop acres were enrolled. You farm corn and must choose your coverage level.", "kicker": "Decide: how much of your crop do you insure?", "fullText": "Farmers buy policies that pay out when yields or revenue fall short, and the government pays part of the premium: $10.4 billion in 2024. Drought and heat were a leading cause of losses in 14 of the 25 years since 2000, and excess moisture caused 27% of losses.\n\nYou farm corn. Higher coverage costs more but pays out sooner when yields drop. The rule from day 11: crop insurance is the safety net most farmers actually use.", "sources": [{"url": "https://www.ers.usda.gov/topics/farm-practices-management/risk-management/crop-insurance-at-a-glance", "label": "USDA ERS, crop insurance at a glance"}]}, "evidence": {"kind": "faceOff", "prompt": "Since 2000, which has more often been a leading cause of losses?", "left": {"name": "Drought and heat", "note": "A leading cause in 14 of 25 years"}, "right": {"name": "Hail alone", "note": "A local, patchy risk"}, "correctIndex": 0, "explanation": "Drought and heat led losses in 14 of the 25 years since 2000. Excess moisture caused 27% of losses."}, "numbers": {"kind": "numberSense", "prompt": "About what share of major field crop acres was enrolled in crop insurance in 2024?", "min": 0, "max": 100, "value": 89, "unit": "%", "explanation": "About 89% of the acreage of eight major field crops."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work for a crop insurance agent. A farmer asks which coverage level to pick.", "prompt": "What do you ask her first?", "options": ["What color is her tractor?", "Which crops did her parents grow?", "How big a loss could she absorb?"], "correctIndex": 2, "consequences": ["Tractor color has no bearing on risk.", "History does not set this year's risk.", "Coverage should match the loss she cannot carry."], "explanation": "The right coverage protects against the losses that would hurt the farm most."}, "proReasoning": "Agents size coverage to the farm's ability to absorb loss.", "commonMistake": "Selling the most coverage to everyone, or the least.", "mentalModel": "Cover what you cannot absorb."}, "invest": {"call": {"kind": "theCall", "situation": "You lend to this farm. She is choosing between low and high coverage.", "prompt": "Which choice protects your loan?", "options": ["Higher coverage that pays out sooner", "The cheapest policy with little cover", "No insurance, to save premium"], "correctIndex": 0, "consequences": ["Payouts help her repay after a bad year.", "Little cover leaves the loan exposed.", "Skipping insurance raises your risk."], "explanation": "Insurance turns a crop disaster into a smaller loss, which protects repayment."}, "proReasoning": "Lenders often prefer, or require, solid coverage. It protects the cash flow behind the loan.", "commonMistake": "Ignoring a borrower's insurance choice.", "mentalModel": "Insurance protects the loan."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers struggle to compare coverage levels. Your startup has yield and price data.", "prompt": "What should your tool show?", "options": ["The latest news about the farm bill", "Each level's cost against its cover", "A list of every insurer's logo"], "correctIndex": 1, "consequences": ["News is not a coverage comparison.", "It makes the trade-off clear.", "Logos do not help choose coverage."], "explanation": "The choice is premium versus protection. A side-by-side view makes it clear."}, "proReasoning": "Founders turn a complex purchase into a clear trade-off.", "commonMistake": "Adding information that does not change the choice.", "mentalModel": "Make the trade-off visible."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why so many farmers buy crop insurance.", "prompt": "What is the main reason?", "options": ["The law makes every farmer buy it", "It always pays out more than it costs", "It protects against losses cheaply"], "correctIndex": 2, "consequences": ["Buying insurance is a choice, though lenders may push it.", "In good years, policies may not pay out.", "Subsidies make cover affordable against real risks."], "explanation": "Weather risks are real, and the government pays part of the premium, so most farmers enroll."}, "proReasoning": "High enrollment usually means the deal is good and the risk is real.", "commonMistake": "Assuming farmers are forced to buy it.", "mentalModel": "Subsidized cover against real risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:136d774073dd$ml$]::text[]),
($ml$f087072e-7564-5827-9680-42d9d4f37cd0$ml$::uuid, $ml$agtech$ml$, 12, 1, $ml${"id": "agtech-d12-c1", "title": "Lasers instead of herbicide", "lessonTitle": "Spraying only the weeds", "slot": 1, "type": "apply", "brief": {"headline": "In October 2024 Carbon Robotics raised $70 million for its LaserWeeder, which uses cameras and lasers to kill weeds. It said the fleet had killed more than 10 billion weeds since 2022.", "kicker": "Apply precision agriculture: what changes when you target only weeds?", "fullText": "Carbon Robotics' Series D brought its total funding to $157 million since its founding in 2018. The LaserWeeder combines computer vision, deep learning, robotics and lasers to find weeds and kill them without chemical herbicides or soil disruption.\n\nThe company says growers in North America, Europe and Australia have used it on 100 crop types, and that it can cut weed control costs by 80%. Like See & Spray, it treats only the weed, not the whole field.", "sources": [{"url": "https://www.therobotreport.com/carbon-robotics-brings-in-70m-to-scale-laserweeder/", "label": "The Robot Report, Carbon Robotics raises $70M, Oct 2024"}, {"url": "https://www.farms.com/news/see-spray-customers-see-59-average-herbicide-savings-in-2024-215613.aspx", "label": "Farms.com, See & Spray customers see 59% herbicide savings"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What do the LaserWeeder and See & Spray have in common?", "options": ["Both work without any cameras", "Both treat only the weeds they detect", "Both spray the whole field evenly"], "correctIndex": 1, "explanation": "Both use cameras and computers to find weeds and act only on them, instead of treating every square foot."}, "numbers": {"kind": "numberSense", "prompt": "How much had Carbon Robotics raised in total by October 2024, in millions of dollars?", "min": 0, "max": 400, "value": 157, "unit": "M", "explanation": "$157 million since 2018, including the $70 million Series D."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Carbon Robotics. They ask who their best early customers are.", "prompt": "Which answer fits the product?", "options": ["Grocery chains that sell fresh produce", "High-value crops with costly weeding", "Farms that never have any weed problems"], "correctIndex": 1, "consequences": ["Stores do not weed fields.", "They feel weed control costs most, often in hand labor.", "No weeds, no need for the machine."], "explanation": "A laser weeder pays back fastest where weeding is expensive, like high-value vegetable crops."}, "proReasoning": "Match an expensive machine to the customers with the costliest version of the problem.", "commonMistake": "Naming every farm as a customer.", "mentalModel": "Sell where the problem costs most."}, "invest": {"call": {"kind": "theCall", "situation": "Carbon Robotics says it can cut weed control costs by 80%. You consider investing.", "prompt": "How do you treat that claim?", "options": ["As a proven fact for every farm", "As irrelevant to the investment", "As a claim to check with growers"], "correctIndex": 2, "consequences": ["Results vary by crop and setup.", "Cost savings are the core of the pitch.", "Customer results test the claim."], "explanation": "The 80% figure comes from the company. Investors verify claims with customer data."}, "proReasoning": "Investors separate company claims from verified results.", "commonMistake": "Taking a pitch number as proof.", "mentalModel": "Verify the claim."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are building a weeding robot. Carbon Robotics raised $157 million already.", "prompt": "Where do you focus?", "options": ["A crop or task the big player serves poorly", "Copy the LaserWeeder exactly, cheaper", "Every crop in every country at once"], "correctIndex": 0, "consequences": ["A niche lets you win without matching its funding.", "Copying a well-funded leader rarely works.", "Spreading thin burns cash fast."], "explanation": "Against a well-funded leader, start where it is weakest."}, "proReasoning": "Founders facing a funded leader pick a niche it neglects.", "commonMistake": "Taking on the leader head-on with less money.", "mentalModel": "Start where the leader is weak."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a laser can weed a field.", "prompt": "How does it work?", "options": ["It pulls weeds out with mechanical arms", "Cameras spot weeds, lasers kill them", "Lasers heat the whole field evenly"], "correctIndex": 1, "consequences": ["It uses lasers, not arms.", "Vision and AI aim the laser at each weed.", "That would harm the crop too."], "explanation": "The machine sees each weed and zaps only it, sparing the crop and skipping herbicide."}, "proReasoning": "Precision tools trade broad treatment for targeted action.", "commonMistake": "Picturing a laser sweeping the whole field.", "mentalModel": "See it, then target it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1ccc9b21b091$ml$]::text[]),
($ml$38f3e402-3ed8-501e-be79-5caad1fe64e5$ml$::uuid, $ml$agtech$ml$, 12, 2, $ml${"id": "agtech-d12-c2", "title": "Cutting the biggest line by machine", "lessonTitle": "Spraying only the weeds", "slot": 2, "type": "connect", "brief": {"headline": "Variable cash costs like fertilizer, seed and chemicals were 47% of Illinois corn's cost in 2025. Deere said See & Spray users cut herbicide use by 59% in 2024.", "kicker": "Connect day 8 and day 12: precision tools attack input costs.", "fullText": "Day 8 showed that variable cash costs, including chemicals, were 47% of the cost of an Illinois corn acre in 2025.\n\nDay 12 shows a tool aimed at that line. Deere said farmers using See & Spray cut herbicide use by 59% on average in 2024, across more than 1 million acres, saving about 8 million gallons of herbicide mix. At high sensitivity, University of Arkansas researchers estimated savings of $30.49 an acre, assuming a $25,000 upgrade cost.", "sources": [{"url": "https://farmdocdaily.illinois.edu/2026/04/cost-to-produce-corn-and-soybeans-in-illinois-2025.html", "label": "farmdoc daily, cost to produce corn and soybeans in Illinois, 2025"}, {"url": "https://www.farms.com/news/see-spray-customers-see-59-average-herbicide-savings-in-2024-215613.aspx", "label": "Farms.com, See & Spray customers see 59% herbicide savings"}, {"url": "https://talkbusiness.net/2025/05/savings-noted-with-university-testing-of-see-spray-herbicide-system/", "label": "Talk Business, university testing of See & Spray"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow how See & Spray saves money.", "steps": ["Cameras scan the field as the sprayer moves", "Computers spot each weed", "Only the nozzles over weeds spray", "Less herbicide is used per acre", "The variable cost line shrinks"], "explanation": "Targeting weeds cuts chemical use, which sits inside the biggest cost line on a corn acre."}, "numbers": {"kind": "numberSense", "prompt": "What savings per acre did Arkansas researchers estimate at high sensitivity, in dollars?", "min": 0, "max": 100, "value": 30, "unit": "$", "explanation": "About $30.49 an acre, assuming a $25,000 upgrade cost."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A precision ag company asks why farmers would pay for See & Spray.", "prompt": "What do you answer?", "options": ["It makes the sprayer look modern", "It lets farmers skip spring planting", "It cuts chemicals, a big cost line"], "correctIndex": 2, "consequences": ["Looks do not justify the price.", "Planting still happens as usual.", "Herbicide is part of the 47% variable cost line."], "explanation": "Chemicals are part of variable cash costs, nearly half of corn's cost. Cutting them pays."}, "proReasoning": "Tie the tool to the cost line it shrinks.", "commonMistake": "Selling technology for its own sake.", "mentalModel": "Tools sell by the cost they cut."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a herbicide maker. Precision spraying is spreading across farms.", "prompt": "What risk does that pose?", "options": ["Lower herbicide volumes per acre", "Higher herbicide demand overall", "No effect on chemical sales"], "correctIndex": 0, "consequences": ["Users cut herbicide use 59% on average.", "Targeted spraying uses less, not more.", "Saved gallons are lost sales."], "explanation": "About 8 million gallons of herbicide mix were saved in 2024. That is volume a chemical maker does not sell."}, "proReasoning": "Investors trace a farmer's saving to the supplier who loses the sale.", "commonMistake": "Missing how efficiency tools shrink input demand.", "mentalModel": "Your saving is someone's lost sale."}, "build_startup": {"call": {"kind": "theCall", "situation": "See & Spray needs a $25,000 upgrade. Your startup could finance the upgrade.", "prompt": "How do you frame the offer?", "options": ["Skip the savings math entirely", "Pay from savings of about $30 an acre", "Pay the full price upfront today"], "correctIndex": 1, "consequences": ["Farmers decide on the savings math.", "Payments match the savings the tool creates.", "Upfront costs stop many farms."], "explanation": "Financing works when payments fit inside the savings per acre."}, "proReasoning": "Founders finance tools out of the savings they create.", "commonMistake": "Asking for a big upfront check in a tight year.", "mentalModel": "Let savings pay the bill."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how much herbicide smart sprayers really save.", "prompt": "What did Deere report for 2024?", "options": ["About 5% less herbicide used", "No change in herbicide use", "About 59% less herbicide"], "correctIndex": 2, "consequences": ["The reported saving was far larger.", "Users reported large savings.", "Across more than 1 million acres."], "explanation": "Deere reported 59% average savings, about 8 million gallons of mix, across more than 1 million acres."}, "proReasoning": "Know the headline number and its source. This one comes from Deere.", "commonMistake": "Forgetting that a company reported the figure.", "mentalModel": "Know the number and who said it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b7b5b6715ec2$ml$]::text[]),
($ml$08de9b93-f801-56ad-9bfb-52c905c41b2b$ml$::uuid, $ml$agtech$ml$, 12, 3, $ml${"id": "agtech-d12-c3", "title": "The sensitivity dial", "lessonTitle": "Spraying only the weeds", "slot": 3, "type": "decide", "brief": {"headline": "University of Arkansas tests found that at See & Spray's lowest sensitivity, missed weeds set seed and Palmer amaranth grew 280% a year. You must pick a setting.", "kicker": "Decide: save more herbicide now, or protect next year?", "fullText": "See & Spray cameras scan more than 2,100 square feet per second and tell each nozzle to spray only weeds. A lower sensitivity sprays less and saves more herbicide this year. But in Arkansas tests, missed weeds set seed, and Palmer amaranth populations grew 280% a year at the lowest setting. Researchers recommend the high sensitivity setting.\n\nYou are setting up the sprayer. The rule from day 12: savings you see this year can cost you next year if the tool is misused.", "sources": [{"url": "https://talkbusiness.net/2025/05/savings-noted-with-university-testing-of-see-spray-herbicide-system/", "label": "Talk Business, university testing of See & Spray"}, {"url": "https://www.farms.com/news/see-spray-customers-see-59-average-herbicide-savings-in-2024-215613.aspx", "label": "Farms.com, See & Spray customers see 59% herbicide savings"}]}, "evidence": {"kind": "faceOff", "prompt": "Which setting did Arkansas researchers recommend?", "left": {"name": "Lowest sensitivity", "note": "Sprays least, saves most now"}, "right": {"name": "High sensitivity", "note": "Catches more weeds"}, "correctIndex": 1, "explanation": "At the lowest setting, escaped weeds set seed and multiplied. High sensitivity protects future years."}, "numbers": {"kind": "numberSense", "prompt": "How fast did Palmer amaranth populations grow a year at the lowest setting, in percent?", "min": 0, "max": 500, "value": 280, "unit": "%", "explanation": "280% a year, as missed weeds set seed."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are an agronomist. A grower wants the lowest setting to save the most herbicide.", "prompt": "What do you advise?", "options": ["Use high sensitivity to stop weeds spreading", "Use the lowest setting to save the most", "Turn the cameras off and spray everything"], "correctIndex": 0, "consequences": ["It protects future years from a weed boom.", "Pigweed grew 280% a year at that setting.", "That gives up the savings entirely."], "explanation": "Researchers recommend high sensitivity. The lowest setting let weeds multiply fast."}, "proReasoning": "Agronomists weigh this year's saving against next year's weed pressure.", "commonMistake": "Maximizing one season's savings.", "mentalModel": "Protect next year's field."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a precision spraying company. Some customers run the lowest setting.", "prompt": "What reputational risk exists?", "options": ["Too few weeds left to spray", "Weed blowups blamed on the tool", "Customers saving too little money"], "correctIndex": 1, "consequences": ["Escaped weeds grow in number.", "Misuse can make the product look bad.", "Low settings save more, not less."], "explanation": "If misused settings let weeds spread, the tool may take the blame."}, "proReasoning": "Investors watch how products are used, not just sold. Misuse can hurt a brand.", "commonMistake": "Assuming a good product guarantees good results.", "mentalModel": "Misuse is a business risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You make software for smart sprayers. Users chase short-term savings.", "prompt": "What feature helps?", "options": ["Default to the lowest sensitivity", "Hide sensitivity settings from users", "Warn when settings risk weed escapes"], "correctIndex": 2, "consequences": ["That is the setting that let weeds spread.", "Hiding controls frustrates growers.", "It guides users toward results that last."], "explanation": "Good defaults and warnings stop misuse that costs farmers later."}, "proReasoning": "Founders design defaults that protect users from costly mistakes.", "commonMistake": "Optimizing the number users see today.", "mentalModel": "Design for next year's result."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how saving herbicide could make weeds worse.", "prompt": "What happens?", "options": ["Missed weeds go to seed and spread", "Herbicide makes weeds grow faster", "Cameras plant new weeds"], "correctIndex": 0, "consequences": ["Pigweed grew 280% a year at the lowest setting.", "Herbicide kills weeds; it does not feed them.", "Cameras only see weeds."], "explanation": "Weeds the sprayer misses set seed, so next year's field has more of them."}, "proReasoning": "Every saving has a trade-off. Here it is weeds left behind.", "commonMistake": "Seeing only the saving, not what it leaves behind.", "mentalModel": "Missed weeds multiply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b7817a27aeb2$ml$]::text[]),
($ml$31a51403-0aa2-502a-b83f-cfe0d238f39f$ml$::uuid, $ml$agtech$ml$, 13, 1, $ml${"id": "agtech-d13-c1", "title": "$32,000 for one acre", "lessonTitle": "What an acre is worth", "slot": 1, "type": "apply", "brief": {"headline": "A 35-acre parcel in Sioux County, Iowa, sold for $32,000 an acre, a state record. The buyer was a local farmer who plans to plant row crops.", "kicker": "Apply land values: why would a farmer pay this much?", "fullText": "The sale beat the previous Iowa record of $30,000 an acre, set in 2022, also in Sioux County. A local farmer bought the land and intends to plant row crops on it.\n\nThe statewide picture is far lower. In 2026 Iowa cropland averaged $10,700 an acre, the highest of any state in USDA's survey, and the US average topped $6,000 for the first time. Small parcels next to a buyer's own fields can draw prices far above the average.", "sources": [{"url": "https://www.brownfieldagnews.com/news/northwest-iowa-farmland-sells-for-32k-per-acre/", "label": "Brownfield, northwest Iowa farmland sells for $32K per acre"}, {"url": "https://farmpolicynews.illinois.edu/2026/08/us-cropland-tops-6000-per-acre-for-first-time-in-2026/", "label": "Farm Policy News, US cropland tops $6,000 per acre in 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why might a neighbor pay far above the state average for a small parcel?", "options": ["Land next to theirs rarely comes up", "Small parcels always yield more per acre", "Iowa law sets prices for small farms"], "correctIndex": 0, "explanation": "Land next to your own fields is scarce. A neighbor may bid high because the chance may not come back for years."}, "numbers": {"kind": "numberSense", "prompt": "How many times the 2026 Iowa cropland average was this $32,000 sale, roughly?", "min": 0, "max": 8, "value": 3, "unit": "x", "explanation": "About 3 times: $32,000 against an Iowa average of $10,700."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a farmland appraisal firm. They ask how to read a record sale.", "prompt": "Which answer shows judgment?", "options": ["Every acre in Iowa is now worth $32,000", "Record sales mean land will keep doubling", "A single small sale may not set the market"], "correctIndex": 2, "consequences": ["One parcel does not reprice a whole state.", "Records say little about future growth.", "The state average was $10,700, far below."], "explanation": "A 35-acre sale to a neighbor is an outlier. Appraisers weigh it against the broader average."}, "proReasoning": "Appraisers separate outliers from the trend. One small neighbor sale is not the market.", "commonMistake": "Treating a headline sale as the typical price.", "mentalModel": "One sale is not the market."}, "invest": {"call": {"kind": "theCall", "situation": "You consider buying Iowa farmland as an investment after the record sale.", "prompt": "Which price should anchor your thinking?", "options": ["The average for comparable land", "The $32,000 record sale", "The lowest price ever paid"], "correctIndex": 0, "consequences": ["Comparable land shows what you would really pay.", "An outlier would overstate the market.", "Old lows do not reflect today's market."], "explanation": "Iowa cropland averaged $10,700 in 2026. Comparable sales, not records, set realistic prices."}, "proReasoning": "Investors anchor on comparable sales, not on headlines.", "commonMistake": "Letting a record set your expectations.", "mentalModel": "Anchor on comparables."}, "build_startup": {"call": {"kind": "theCall", "situation": "Buyers and sellers struggle to know what a parcel is worth. Your startup has sales data.", "prompt": "What product fits?", "options": ["Photos of farms for sale", "Value estimates from comparable sales", "A list of only the record sales"], "correctIndex": 1, "consequences": ["Photos do not set prices.", "Comparables give a realistic range.", "Records alone mislead buyers."], "explanation": "Comparable sales give a fair range. Records are outliers."}, "proReasoning": "Founders turn scattered sales into a fair value range.", "commonMistake": "Featuring headlines instead of typical prices.", "mentalModel": "Price from comparables."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend reads about the $32,000 sale and thinks Iowa farmers are all rich.", "prompt": "What's the fuller picture?", "options": ["Every Iowa acre sells for $32,000 now", "Farmers sell land every year for profit", "Most Iowa land is worth about a third of that"], "correctIndex": 2, "consequences": ["One small sale does not set all prices.", "Most farmers keep their land for decades.", "The 2026 average was $10,700 an acre."], "explanation": "Record sales grab headlines. The typical Iowa acre was worth about $10,700 in 2026."}, "proReasoning": "Headlines show the extremes. Look for the average.", "commonMistake": "Generalizing from a record.", "mentalModel": "Records are not averages."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1f9e37516295$ml$]::text[]),
($ml$a99b4cd3-0274-5a44-9454-dad273692892$ml$::uuid, $ml$agtech$ml$, 13, 2, $ml${"id": "agtech-d13-c2", "title": "Losing money, gaining wealth", "lessonTitle": "What an acre is worth", "slot": 2, "type": "connect", "brief": {"headline": "Illinois corn on rented land was projected to lose $45 to $53 an acre in 2026. That same year, US cropland values rose 3.3% to a record $6,020 an acre.", "kicker": "Connect day 7 and day 13: the crop loses, the land gains.", "fullText": "Day 7 showed the acre P&L: at $4.50 corn, rented Illinois acres were projected to lose $45 to $53, with break-even near $4.80.\n\nDay 13 shows the land under that acre. US cropland averaged $6,020 an acre in 2026, up 3.3% in a year and 21.8% since 2022. Iowa averaged $10,700 and Illinois $10,200. Gains were slower than the 4.7% of 2025, but values kept climbing even with thin crop margins.", "sources": [{"url": "https://farmdocdaily.illinois.edu/2026/05/spring-revision-to-2026-illinois-crop-budgets.html", "label": "farmdoc daily, spring revision to 2026 Illinois crop budgets"}, {"url": "https://farmpolicynews.illinois.edu/2026/08/us-cropland-tops-6000-per-acre-for-first-time-in-2026/", "label": "Farm Policy News, US cropland tops $6,000 per acre in 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "In 2026, which grew the owner's wealth more on a typical Illinois acre?", "left": {"name": "The corn crop", "note": "Projected loss on rented land"}, "right": {"name": "The land itself", "note": "Cropland values up 3.3%"}, "correctIndex": 1, "explanation": "The crop lost money on rented land, while land values rose. Land is where farm wealth is held."}, "numbers": {"kind": "numberSense", "prompt": "By how much did US cropland values rise from 2022 to 2026, in percent?", "min": 0, "max": 60, "value": 22, "unit": "%", "explanation": "About 21.8%, to $6,020 an acre."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A farm lender asks why it still lends against land when crop margins are negative.", "prompt": "What do you answer?", "options": ["Land holds value even when crops lose", "Crops are more valuable than land", "Lenders ignore land when lending"], "correctIndex": 0, "consequences": ["Land rose 3.3% while corn lost money.", "Land is the bigger store of value.", "Land is the main collateral."], "explanation": "Farmland kept rising through thin margins, which makes it strong collateral."}, "proReasoning": "Separate the operating business from the asset. Lenders lean on the asset.", "commonMistake": "Judging farm wealth by crop income alone.", "mentalModel": "Land holds the wealth."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh buying farmland while crops lose money.", "prompt": "What is the main bet you would be making?", "options": ["That rent becomes the main return", "That land values keep holding up", "That corn prices double next year"], "correctIndex": 1, "consequences": ["Crop margins are too thin to drive returns.", "Values rose 21.8% since 2022.", "A price spike is not needed for land to gain."], "explanation": "With thin crop margins, the return on farmland has leaned on rising land values."}, "proReasoning": "Investors name the real source of return. For farmland lately, that is appreciation.", "commonMistake": "Assuming the crop pays for the land.", "mentalModel": "Name where the return comes from."}, "build_startup": {"call": {"kind": "theCall", "situation": "Farmers are land rich but cash poor this year. Your startup works in farm finance.", "prompt": "What product fits that situation?", "options": ["Loans that ignore land entirely", "Tools to sell farmland quickly", "Land-backed credit for thin years"], "correctIndex": 2, "consequences": ["It ignores the farm's biggest asset.", "Most farmers want to keep their land.", "Land value supports cash flow in weak years."], "explanation": "Land is worth a lot even when crops lose. Finance can tap that value to bridge bad years."}, "proReasoning": "Founders match products to the balance sheet: rich in land, short on cash.", "commonMistake": "Ignoring the farm's biggest asset.", "mentalModel": "Lend against the asset."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how farmland can be worth more each year if farming loses money.", "prompt": "What explains it?", "options": ["Land is a long-term store of wealth", "Land values are set by crop profits each year", "Farmland is never sold"], "correctIndex": 0, "consequences": ["Buyers value it for decades, not one season.", "Values rose even as margins shrank.", "Farmland is bought and sold regularly."], "explanation": "Land holds wealth over the long run, even when one season's crop loses money."}, "proReasoning": "Assets and income can move differently. Land is priced for the long run.", "commonMistake": "Expecting land prices to follow one year's profits.", "mentalModel": "Land is priced for decades."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cbf6d675eac9$ml$]::text[]),
($ml$78de768c-ccb5-5f6c-8a65-833f3324f48c$ml$::uuid, $ml$agtech$ml$, 13, 3, $ml${"id": "agtech-d13-c3", "title": "Buy the farm or keep renting", "lessonTitle": "What an acre is worth", "slot": 3, "type": "decide", "brief": {"headline": "In 2026 Iowa cropland averaged $10,700 an acre, Ohio $10,100 and Kansas $3,540. You farm in Iowa and can buy 80 acres at about the state average.", "kicker": "Decide: is buying land worth it at these prices?", "fullText": "USDA's July 2026 survey put US cropland at $6,020 an acre, up 3.3% in a year. Iowa cropland averaged $10,700, about three times Kansas at $3,540. Pasture averaged $2,000. Values climbed even while crop margins were thin.\n\nYou farm in Iowa. You can buy 80 acres at about $10,700 an acre, or keep renting. The rule from day 13: land is the asset that holds wealth even when crops lose money.", "sources": [{"url": "https://farmpolicynews.illinois.edu/2026/08/us-cropland-tops-6000-per-acre-for-first-time-in-2026/", "label": "Farm Policy News, US cropland tops $6,000 per acre in 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each point favor buying or renting?", "buckets": ["Favors buying", "Favors renting"], "items": [{"text": "Land has held value through thin margins", "bucket": 0}, {"text": "You want to build long-term wealth", "bucket": 0}, {"text": "You have little cash and a big loan would strain you", "bucket": 1}, {"text": "Crop margins are negative this year", "bucket": 1}], "explanation": "Buying builds wealth in an asset that holds value. Renting keeps cash free when margins are thin."}, "numbers": {"kind": "numberSense", "prompt": "At $10,700 an acre, what would 80 acres cost, in thousands of dollars?", "min": 0, "max": 1500, "value": 856, "unit": "K", "explanation": "About $856,000: 80 times $10,700."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work at a farm credit office. A young farmer asks whether to buy the 80 acres.", "prompt": "What do you help her test first?", "options": ["Whether her neighbors will approve", "Whether her cash flow can carry the loan", "Whether the land has a nice view"], "correctIndex": 1, "consequences": ["Neighbors do not decide her finances.", "Thin margins make loan payments the key risk.", "Views do not repay loans."], "explanation": "Land builds wealth, but payments come from cash flow, which is thin this year."}, "proReasoning": "Lenders test cash flow before celebrating the asset.", "commonMistake": "Approving a loan on land value alone.", "mentalModel": "Cash flow first, asset second."}, "invest": {"call": {"kind": "theCall", "situation": "You compare buying land in Iowa at $10,700 and in Kansas at $3,540.", "prompt": "What does the price gap mostly reflect?", "options": ["A pricing error that will vanish soon", "Iowa land being newer", "Differences in what the land can produce"], "correctIndex": 2, "consequences": ["Such gaps persist for good reasons.", "Land is not newer or older.", "Better soils and rain support higher prices."], "explanation": "Land prices reflect productivity. Iowa's soils and rainfall support higher values."}, "proReasoning": "Investors explain price gaps before chasing them. Productivity drives most of them.", "commonMistake": "Assuming cheaper land is automatically a bargain.", "mentalModel": "Price follows productivity."}, "build_startup": {"call": {"kind": "theCall", "situation": "Many young farmers cannot afford land at $10,700 an acre. Your startup wants to help.", "prompt": "Which model fits?", "options": ["Investors buy land, farmers lease it", "Farmers buy land with no financing", "An online forum on land prices"], "correctIndex": 0, "consequences": ["Farmers get access without the full price.", "Few can pay $856,000 in cash.", "Talk does not provide land."], "explanation": "Splitting ownership from farming lets young farmers use land without buying it."}, "proReasoning": "Founders separate who owns land from who farms it. That opens access.", "commonMistake": "Assuming farmers must own land to farm it.", "mentalModel": "Separate owning from farming."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why farmers buy land at high prices when crops lose money.", "prompt": "What is the main reason?", "options": ["The law requires farmers to own land", "Land tends to hold and grow its value", "Land always pays for itself in one year"], "correctIndex": 1, "consequences": ["Many farmers rent instead of owning.", "Cropland rose 3.3% in 2026.", "At current margins, it can take decades."], "explanation": "Farmland has tended to hold value over time, so buyers see it as wealth, not just a crop field."}, "proReasoning": "People buy land for the long run, not for one harvest.", "commonMistake": "Judging land purchases by one year's profit.", "mentalModel": "Land is a long game."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0ebfb8abe7c6$ml$]::text[]),
($ml$4a94a0b2-7423-5700-8fbb-9538f1a3a258$ml$::uuid, $ml$agtech$ml$, 14, 1, $ml${"id": "agtech-d14-c1", "title": "Iowa's $270 rent", "lessonTitle": "The rent check", "slot": 1, "type": "apply", "brief": {"headline": "Iowa State University found the average 2026 cash rent for an acre of Iowa cropland was $270, down $1 from 2025. West central Iowa had the highest average, $292.", "kicker": "Apply the rent check: who carries the risk in a cash rent deal?", "fullText": "Iowa State University Extension surveys rents every year. In 2026 the average cash rent for Iowa cropland was $270 an acre, down 0.4% from 2025. The west central crop district had the highest average, at $292.\n\nIn a cash rent deal, the farmer pays a fixed sum per acre whatever the harvest. The landowner's income is steady and the farmer carries the risk. With crop margins thin, rents held almost flat.", "sources": [{"url": "https://www.profarmer.com/news/agriculture-news/2026-average-iowa-cash-rent-eases", "label": "Pro Farmer, 2026 average Iowa cash rent eases"}, {"url": "https://farmpolicynews.illinois.edu/2026/08/us-cropland-tops-6000-per-acre-for-first-time-in-2026/", "label": "Farm Policy News, US cropland tops $6,000 per acre in 2026"}]}, "evidence": {"kind": "faceOff", "prompt": "In a cash rent deal, who carries the risk of a bad harvest?", "left": {"name": "The landowner", "note": "Gets a fixed rent per acre"}, "right": {"name": "The farmer", "note": "Pays the rent whatever the yield"}, "correctIndex": 1, "explanation": "The rent is fixed. If yields or prices fall, the farmer absorbs the loss."}, "numbers": {"kind": "numberSense", "prompt": "What was the average 2026 cash rent for Iowa cropland, in dollars per acre?", "min": 0, "max": 500, "value": 270, "unit": "$", "explanation": "$270 an acre, down $1 from 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a farm management company. They ask why Iowa rents barely moved in 2026.", "prompt": "Which answer is best?", "options": ["Thin margins limited what farmers could pay", "Landowners stopped caring about income", "Rent is fixed by state law each year"], "correctIndex": 0, "consequences": ["Tenants pushed back as crop returns stayed low.", "Owners still want income.", "Rents are set by negotiation, not law."], "explanation": "Rent follows what the land can earn. With thin margins, rents held near flat."}, "proReasoning": "Tie rent moves to crop returns. That shows you understand both sides of the lease.", "commonMistake": "Treating rent as independent of farm income.", "mentalModel": "Rent follows returns."}, "invest": {"call": {"kind": "theCall", "situation": "You own Iowa farmland rented at $270 an acre. A tenant asks to switch to a flexible lease.", "prompt": "What changes for you?", "options": ["Nothing about your risk changes", "You share more of the harvest risk", "Your income becomes fully guaranteed"], "correctIndex": 1, "consequences": ["The lease type shifts who carries risk.", "Flexible rent moves with yields or prices.", "Flexible leases add variability."], "explanation": "A fixed cash rent puts the risk on the farmer. A flexible lease shares it with the owner."}, "proReasoning": "Landowners choose how much risk to carry through the lease type.", "commonMistake": "Missing that lease terms shift risk.", "mentalModel": "The lease decides who bears risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Landowners and tenants argue about fair rent every year. Your startup has local data.", "prompt": "What should you offer?", "options": ["A national average for every farm", "A guaranteed rent price", "Local rent benchmarks by district"], "correctIndex": 2, "consequences": ["A national figure hides local gaps.", "No one can guarantee rents.", "Rents vary by district, like $292 in west central."], "explanation": "Rents differ by area. Local benchmarks help both sides agree."}, "proReasoning": "Founders give negotiators shared local facts.", "commonMistake": "Using national averages for local deals.", "mentalModel": "Local data settles local deals."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how much it costs to rent an acre of Iowa farmland.", "prompt": "What is the 2026 average?", "options": ["About $270 a year", "About $27 a year", "About $2,700 a year"], "correctIndex": 0, "consequences": ["The ISU survey average was $270.", "Ten times too low.", "Ten times too high."], "explanation": "Iowa cropland rented for an average of $270 an acre in 2026."}, "proReasoning": "Know the order of magnitude. Rent is hundreds per acre, value is thousands.", "commonMistake": "Mixing up rent and land value.", "mentalModel": "Rent hundreds, value thousands."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:64bc4e94bd1f$ml$]::text[]),
($ml$fb2c8251-fa78-5a7d-9463-daa178e4608b$ml$::uuid, $ml$agtech$ml$, 14, 2, $ml${"id": "agtech-d14-c2", "title": "A 2.7% yield on a rising asset", "lessonTitle": "The rent check", "slot": 2, "type": "connect", "brief": {"headline": "US cropland averaged $6,020 an acre in 2026 and rented for $160. That rent is a gross return of about 2.7% a year.", "kicker": "Connect day 13 and day 14: value, rent and the gap between.", "fullText": "Day 13 showed land values: US cropland reached $6,020 an acre in 2026, up 21.8% since 2022.\n\nDay 14 shows the rent on that land: $160 an acre on average, down $1. California led at $331, then Hawaii, Iowa at $271 and Illinois at $261. Divide rent by value and the landowner earns about 2.7% a year before costs. Landowners accept that because values have tended to rise over time.", "sources": [{"url": "https://farmpolicynews.illinois.edu/2026/08/us-cropland-tops-6000-per-acre-for-first-time-in-2026/", "label": "Farm Policy News, US cropland tops $6,000 per acre in 2026"}]}, "evidence": {"kind": "buildChain", "prompt": "Work out a landowner's total return in order.", "steps": ["Start with the yearly rent per acre", "Divide rent by the land's value", "That gives the rent yield, about 2.7%", "Add the change in land value", "The sum is the total return"], "explanation": "Rent pays a little each year. Rising values have paid the rest."}, "numbers": {"kind": "numberSense", "prompt": "What gross yield does a $160 rent give on $6,020 land, in percent?", "min": 0, "max": 10, "value": 2.7, "unit": "%", "explanation": "About 2.7% a year, before costs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A farmland fund asks you how landowners earn their return.", "prompt": "What do you say?", "options": ["From selling crops they grow", "Small rent plus rising land value", "Mostly from very high rent checks"], "correctIndex": 1, "consequences": ["Non-farming owners rent; they do not sell crops.", "Rent yields about 2.7%, and values rose too.", "Rent alone is a modest return."], "explanation": "Rent is about 2.7% of value. Appreciation has made up the rest of the return."}, "proReasoning": "Split the return into income and appreciation. Funds think that way.", "commonMistake": "Overstating rent as the main return.", "mentalModel": "Income plus appreciation."}, "invest": {"call": {"kind": "theCall", "situation": "A bond pays more than the 2.7% farmland rent yield. You weigh both.", "prompt": "What could still make farmland attractive?", "options": ["Rent that always beats bonds", "A guarantee against losses", "Expected growth in land value"], "correctIndex": 2, "consequences": ["Rent yields here are below the bond.", "Land values can fall too.", "Values have tended to rise over time."], "explanation": "The rent yield is modest. Farmland investors also count on value growth."}, "proReasoning": "Investors compare total return, not just income.", "commonMistake": "Comparing only rent yield to bond yield.", "mentalModel": "Compare total return."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup lets small investors buy shares in farmland.", "prompt": "What must you explain clearly?", "options": ["Most return depends on land value", "Rent alone gives a high yield", "Farmland values never fall"], "correctIndex": 0, "consequences": ["Rent yields only about 2.7%.", "That overstates the rent return.", "Values can and do fall."], "explanation": "With a 2.7% rent yield, investors rely on appreciation, which can go down as well as up."}, "proReasoning": "Founders set honest expectations about where returns come from.", "commonMistake": "Overselling rent income to new investors.", "mentalModel": "Be honest about the return mix."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why owners rent out land for so little compared with its price.", "prompt": "What explains it?", "options": ["Owners do not want any income", "They expect the land to gain value", "Rent is capped by federal law"], "correctIndex": 1, "consequences": ["Owners still collect rent.", "Rising values have paid most of the return.", "Rents are negotiated, not capped."], "explanation": "A 2.7% rent is low, but owners have also gained from rising land values."}, "proReasoning": "Low income can make sense when the asset grows.", "commonMistake": "Judging the deal by rent alone.", "mentalModel": "Growth makes up for low rent."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5e5f0c136df8$ml$]::text[]),
($ml$10de1817-09a0-5195-bff9-3cf54540f2e4$ml$::uuid, $ml$agtech$ml$, 14, 3, $ml${"id": "agtech-d14-c3", "title": "The rent renewal talk", "lessonTitle": "The rent check", "slot": 3, "type": "decide", "brief": {"headline": "US cropland rented for $160 an acre in 2026, and Iowa for $271. You rent 300 acres in Iowa, and your landlord wants to raise the rent.", "kicker": "Decide: how do you respond to a rent increase?", "fullText": "USDA put average cropland rent at $160 an acre in 2026, down $1. Iowa averaged $271 and Illinois $261. In a cash rent deal, the farmer pays a fixed sum per acre whatever the harvest.\n\nYou rent 300 acres in Iowa. Your landlord wants more. Crop margins are thin this year. The rule from day 14: rent pays a little each year, and rising values pay the rest.", "sources": [{"url": "https://farmpolicynews.illinois.edu/2026/08/us-cropland-tops-6000-per-acre-for-first-time-in-2026/", "label": "Farm Policy News, US cropland tops $6,000 per acre in 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which offer shares risk between you and the landlord?", "options": ["Paying the full rent in advance", "A flexible lease tied to yield or price", "A higher fixed rent for five years"], "correctIndex": 1, "explanation": "A flexible lease rises in good years and falls in bad ones, so both sides share the risk."}, "numbers": {"kind": "numberSense", "prompt": "At $271 an acre, what is the yearly rent on 300 acres, in thousands of dollars?", "min": 0, "max": 150, "value": 81, "unit": "K", "explanation": "About $81,300: 300 times $271."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage farms for absentee landlords. A tenant pushes back on a rent increase.", "prompt": "What do you bring to the talk?", "options": ["A demand to pay or leave", "Last decade's rent figures only", "Local rents and crop returns"], "correctIndex": 2, "consequences": ["It risks losing a good tenant.", "Old figures miss today's margins.", "Facts on both sides support a fair deal."], "explanation": "Fair rent reflects local markets and what the land earns. Data keeps both sides reasonable."}, "proReasoning": "Managers ground rent talks in local benchmarks and crop returns.", "commonMistake": "Negotiating without data.", "mentalModel": "Benchmarks keep talks fair."}, "invest": {"call": {"kind": "theCall", "situation": "You are the landlord. Your tenant shows budgets with thin margins.", "prompt": "What protects your long-term return?", "options": ["Keeping a good tenant at a fair rent", "Raising rent until the tenant leaves", "Leaving the land empty"], "correctIndex": 0, "consequences": ["A reliable tenant protects income and land care.", "Turnover costs time and income.", "Empty land earns nothing."], "explanation": "Rent is a small part of your return. A steady tenant protects it and keeps the land in good shape."}, "proReasoning": "Landlords weigh tenant quality as much as the rent number.", "commonMistake": "Squeezing a tenant whose margins are already thin.", "mentalModel": "A good tenant is worth keeping."}, "build_startup": {"call": {"kind": "theCall", "situation": "Tenants and landlords want leases that adjust fairly. Your startup builds lease software.", "prompt": "What feature matters most?", "options": ["One fixed rent for the next 20 years", "Rent that adjusts with yield or price", "Printed leases with fancy covers"], "correctIndex": 1, "consequences": ["Long fixed rents ignore changing margins.", "It shares risk without yearly fights.", "Covers do not change terms."], "explanation": "Flexible leases that adjust by formula reduce yearly negotiations."}, "proReasoning": "Founders turn a yearly argument into an agreed formula.", "commonMistake": "Digitizing the old fight instead of fixing it.", "mentalModel": "Replace fights with formulas."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a farmer would rent land instead of buying it.", "prompt": "Which reason fits?", "options": ["Renters own the land after a year", "Buying land is not allowed", "Rent costs far less cash than buying"], "correctIndex": 2, "consequences": ["Renting never transfers ownership.", "Anyone can buy land.", "$271 a year versus about $10,700 to buy an acre."], "explanation": "Renting lets farmers use land for a small yearly payment instead of a huge purchase."}, "proReasoning": "Renting trades ownership for cash flexibility.", "commonMistake": "Thinking farmers must own the land they farm.", "mentalModel": "Rent for flexibility."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f67d97de5992$ml$]::text[]),
($ml$3b342d8e-03e8-5119-b035-2dc817921707$ml$::uuid, $ml$agtech$ml$, 15, 1, $ml${"id": "agtech-d15-c1", "title": "The biggest private farmland owner", "lessonTitle": "The landlords who do not farm", "slot": 1, "type": "apply", "brief": {"headline": "Bill Gates owns about 242,000 acres of US farmland, The Land Report says. His firm Cascade Investment bought it in big tranches, including two deals worth over $690 million.", "kicker": "Apply the lesson: who farms land that a billionaire owns?", "fullText": "The Land Report says Gates holds farmland in close to 20 states, bought through his investment firm Cascade Investment, which views farmland as a stable, long-term asset. Purchases included farmland bought from CPPIB in 2017 and the 100 Circles acreage in Washington's Horse Heaven Hills in 2018, together more than $690 million.\n\nCascade's subsidiary Cottonwood Ag Management handles operations. Gates is the most famous of the landowners who do not farm: about 79% of rented US farmland belongs to non-farmers.", "sources": [{"url": "https://landreport.com/land-report-100/bill-gates", "label": "The Land Report, Bill Gates"}, {"url": "https://www.farmanddairy.com/news/usda-survey-most-rented-farmland-is-owned-by-non-farmers/907464.html", "label": "Farm and Dairy, most rented farmland is owned by non-farmers"}]}, "evidence": {"kind": "sortSignal", "prompt": "Who does what on land owned by an investor like Cascade?", "buckets": ["Owner", "Operator"], "items": [{"text": "Holds the land as a long-term asset", "bucket": 0}, {"text": "Collects rent or a share of returns", "bucket": 0}, {"text": "Plants, sprays and harvests the crops", "bucket": 1}, {"text": "Manages the day-to-day farm work", "bucket": 1}], "explanation": "Investors own the asset. Farmers and managers run the fields."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand acres of US farmland does Gates own?", "min": 0, "max": 600, "value": 242, "unit": "K", "explanation": "About 242,000 acres, per The Land Report."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a farmland management firm like Cottonwood Ag. They ask what the job involves.", "prompt": "Which answer fits?", "options": ["Writing farm subsidy laws", "Running land for owners who do not farm", "Selling crops directly to shoppers"], "correctIndex": 1, "consequences": ["Laws are written by Congress.", "That is the core of farmland management.", "Managers rarely sell food to shoppers."], "explanation": "Managers handle farmland for owners, like investors, who do not farm it themselves."}, "proReasoning": "Show you see the split between owners and operators.", "commonMistake": "Assuming the owner is the farmer.", "mentalModel": "Owners and operators differ."}, "invest": {"call": {"kind": "theCall", "situation": "Cascade calls farmland a stable, long-term asset. You consider the same strategy.", "prompt": "What makes farmland fit that description?", "options": ["Fast profits from each harvest", "Guaranteed rent increases", "Values that hold up over time"], "correctIndex": 2, "consequences": ["Crop margins are often thin.", "Rents can stay flat or fall.", "Farmland has tended to hold value through thin years."], "explanation": "Investors like farmland for its stability over decades, not for quick harvest profits."}, "proReasoning": "Investors buy farmland for stability and long-run value.", "commonMistake": "Expecting farmland to deliver fast returns.", "mentalModel": "Farmland is a slow, steady asset."}, "build_startup": {"call": {"kind": "theCall", "situation": "Big investors own farmland they never visit. Your startup has field data tools.", "prompt": "What do these owners need?", "options": ["Clear reports on how their land is managed", "Tools to drive the tractors themselves", "Recipes for the crops grown"], "correctIndex": 0, "consequences": ["Distant owners need visibility into their asset.", "They hire operators to do that.", "Recipes do not help an investor."], "explanation": "Absentee owners rely on managers. Reports on yields, soil and care help them track the asset."}, "proReasoning": "Founders serve the distant owner's need for visibility.", "commonMistake": "Building for the owner as if they were the farmer.", "mentalModel": "Give owners visibility."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend hears Gates owns farmland and pictures him driving a combine.", "prompt": "What is closer to reality?", "options": ["The land sits empty and unused", "Managers and farmers run it for him", "He farms every single acre himself"], "correctIndex": 1, "consequences": ["The land is farmed.", "Cottonwood Ag Management handles operations.", "No owner farms 242,000 acres personally."], "explanation": "Gates is an owner, not an operator. Managers and farmers work the land."}, "proReasoning": "Separate owning land from working it.", "commonMistake": "Assuming the owner does the farming.", "mentalModel": "Owning is not farming."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bbc78192af4b$ml$]::text[]),
($ml$20307de8-89a0-5e64-a060-1124ad1e5df6$ml$::uuid, $ml$agtech$ml$, 15, 2, $ml${"id": "agtech-d15-c2", "title": "How farms grow without buying", "lessonTitle": "The landlords who do not farm", "slot": 2, "type": "connect", "brief": {"headline": "The average US farm grew from 444 acres in 2018 to 469 in 2025. About 39% of US farmland is rented, and 79% of rented land is owned by non-farmers.", "kicker": "Connect day 4 and day 15: farms grow by renting from others.", "fullText": "Day 4 showed consolidation: about 1.9 million farms in 2025, fewer each year, with the average farm growing from 444 to 469 acres.\n\nDay 15 shows how much of that land is rented. USDA's 2024 land tenure survey counted 348 million rented acres held by more than 2 million landowners. About 79% of rented land belongs to people who do not farm. Many inherited land they never farmed, so a growing farmer often expands by renting rather than buying.", "sources": [{"url": "https://www.dtnpf.com/agriculture/web/AG/news/article/2026/02/17/us-agriculture-loses-15-000-farms", "label": "DTN on USDA Farms and Land in Farms 2025"}, {"url": "https://www.farmanddairy.com/news/usda-survey-most-rented-farmland-is-owned-by-non-farmers/907464.html", "label": "Farm and Dairy, most rented farmland is owned by non-farmers"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["About 39% of US farmland is rented.", "Most rented land is owned by active farmers.", "Rented land totals about 348 million acres."], "fakeIndex": 1, "explanation": "About 79% of rented land is owned by non-farmers. Active farmers own a minority of it."}, "numbers": {"kind": "numberSense", "prompt": "How many million acres of US farmland are rented?", "min": 0, "max": 800, "value": 348, "unit": "M", "explanation": "About 348 million acres, held by more than 2 million landowners."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An agtech sales team asks you who controls access to farmland.", "prompt": "What do you tell them?", "options": ["Only the farmers who work the land", "The federal government directly", "Many landowners who do not farm it"], "correctIndex": 2, "consequences": ["Farmers often rent the land they work.", "Most farmland is privately owned.", "79% of rented land is owned by non-farmers."], "explanation": "Non-farming landlords own most rented farmland, so they shape who farms it."}, "proReasoning": "Know that the landowner and the operator are often two different customers.", "commonMistake": "Selling only to operators when owners make land decisions.", "mentalModel": "Owners shape access to land."}, "invest": {"call": {"kind": "theCall", "situation": "You study how farms expand. Few landowners plan to sell.", "prompt": "How do most growing farms add acres?", "options": ["By renting from non-farming owners", "By buying land from the government", "By clearing new forest each year"], "correctIndex": 0, "consequences": ["Rented land is a large share of farmland.", "Most farmland is privately held.", "Land in farms is actually falling."], "explanation": "With 39% of farmland rented and few planned sales, renting is the main path to scale."}, "proReasoning": "Investors see rented land as the engine of consolidation.", "commonMistake": "Assuming farms grow mainly by buying.", "mentalModel": "Farms grow by renting."}, "build_startup": {"call": {"kind": "theCall", "situation": "Growing farmers need more land to rent. Many landlords are distant heirs.", "prompt": "What product fits?", "options": ["A crop price ticker", "Matching landlords with good tenants", "A tool to sell land at auction fast"], "correctIndex": 1, "consequences": ["It does not connect owners and tenants.", "It connects distant owners with growing farmers.", "Few owners plan to sell."], "explanation": "Non-farming owners need tenants, and growing farmers need land. Matching them meets both needs."}, "proReasoning": "Founders connect the two sides of the land market: owners and operators.", "commonMistake": "Building for sales when most land changes hands by renting.", "mentalModel": "Match owners and tenants."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend assumes a big farm owns all the land it plants.", "prompt": "What's more likely?", "options": ["It owns every acre outright", "It borrows land for free", "It rents a lot of it from others"], "correctIndex": 2, "consequences": ["Many large farms rent much of their land.", "Rented land comes with rent.", "About 39% of farmland is rented."], "explanation": "Farms often grow by renting land from owners who do not farm."}, "proReasoning": "Ask who owns the land under a farm. It is often someone else.", "commonMistake": "Assuming farm size equals land owned.", "mentalModel": "Farm size is not ownership."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:867c6028bf7f$ml$]::text[]),
($ml$08dcb3eb-014d-58fb-8b4b-523331766b19$ml$::uuid, $ml$agtech$ml$, 15, 3, $ml${"id": "agtech-d15-c3", "title": "Meeting the 75-year-old landlord", "lessonTitle": "The landlords who do not farm", "slot": 3, "type": "decide", "brief": {"headline": "Non-farming landlords average 69.2 years old, against 58.1 for farmers, and plan to sell only about 5% of their acres in five years. You want to rent more land.", "kicker": "Decide: how do you approach an older landlord?", "fullText": "USDA's 2024 land tenure survey, released in March 2026, found that more than a third of non-farming landlords are 75 or older, and they rent out over 40% of rented acres. Non-farming landlords own about 276 million rented acres, and many inherited land they never farmed. They plan to sell only about 5% of their acres in the next five years; most land passes on through families.\n\nYou are a young farmer who wants to rent more. The rule from day 15: those who own the land and those who farm it are often different people.", "sources": [{"url": "https://www.farmanddairy.com/news/usda-survey-most-rented-farmland-is-owned-by-non-farmers/907464.html", "label": "Farm and Dairy, most rented farmland is owned by non-farmers"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Since few landlords plan to sell, what is the likeliest way to gain land?", "options": ["Build trust to become their tenant", "Wait for a wave of land sales soon", "Ask the government for land"], "correctIndex": 0, "explanation": "Landlords plan to sell only about 5% in five years. Renting from them is the realistic path."}, "numbers": {"kind": "numberSense", "prompt": "What is the average age of non-farming principal landlords?", "min": 0, "max": 100, "value": 69, "unit": "years", "explanation": "About 69.2 years, against 58.1 for farmers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work at a bank's farm desk. A young client asks how to win a lease from an older landlord.", "prompt": "What do you suggest?", "options": ["Show care for the land and a clear plan", "Offer the highest rent and nothing else", "Wait until the land is sold"], "correctIndex": 0, "consequences": ["Older owners often value stewardship and trust.", "Price alone may not win a long relationship.", "Few landlords plan to sell soon."], "explanation": "Many landlords inherited land and care how it is treated. Trust and stewardship matter."}, "proReasoning": "Advisors coach clients to win leases on trust, not price alone.", "commonMistake": "Treating a lease like a pure bidding war.", "mentalModel": "Win leases on trust."}, "invest": {"call": {"kind": "theCall", "situation": "More than a third of non-farming landlords are 75 or older. You study land markets.", "prompt": "What should you expect over the next decade?", "options": ["Landlords moving onto their farms", "Much land passing to heirs, not sold", "A flood of farmland for sale"], "correctIndex": 1, "consequences": ["Few non-farming owners will start farming.", "Most land passes on through families.", "Owners plan to sell only about 5% in five years."], "explanation": "Aging owners mostly pass land to heirs. Sales stay limited."}, "proReasoning": "Investors read demographics into supply. Inheritance keeps land off the market.", "commonMistake": "Assuming old owners means many sales.", "mentalModel": "Land passes through families."}, "build_startup": {"call": {"kind": "theCall", "situation": "Land will pass to heirs who may live far away. Your startup serves landowners.", "prompt": "What need will grow?", "options": ["Tools for owners who farm every day", "Online ads for new tractors", "Help for heirs who inherit farmland"], "correctIndex": 2, "consequences": ["Most owners of rented land do not farm.", "Ads do not manage land.", "Distant heirs need help finding tenants and managing land."], "explanation": "As land passes to heirs who do not farm, demand for land management help grows."}, "proReasoning": "Founders spot shifts like inheritance and build for the new owners.", "commonMistake": "Building for yesterday's landowner.", "mentalModel": "Build for the next owner."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why young farmers struggle to find land.", "prompt": "Which fact explains much of it?", "options": ["Owners rarely sell their land", "There is no farmland left in the US", "Young people may not legally farm"], "correctIndex": 0, "consequences": ["Only about 5% is planned for sale in five years.", "About 874 million acres are still farmed.", "No law bars young farmers."], "explanation": "Land rarely comes up for sale, so young farmers mostly rent from existing owners."}, "proReasoning": "Supply, not demand, often limits new farmers.", "commonMistake": "Thinking land is simply too expensive for everyone.", "mentalModel": "Little land comes up for sale."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:11cedd816ca4$ml$]::text[])
